window.BUNDLED_DUNGEONS={"schema":1,"source":"https://github.com/timmseth/omniverse","dungeons":[{"id":"tropelandia.dungeon.glintfang-hoard","code":"DRG","name":"Glintfang's Hoard","universe":"tropelandia","place":{"id":"tropelandia.region.glittering-sands","name":"Glittering Sands","path":["Tropelandia","Material Plane","Gleamhaven","Mildew Sun","Tropos","Mainland","Glittering Sands"]},"levelRange":[8,10],"tone":"sly parody","tags":["dragon","desert","treasure","negotiation","heist"],"summary":"Glintfang is a young gold dragon with a head for business, a hoard she calls a portfolio and a long list of visiting heroes she has politely turned into guests. Her lair is a sandstone cathedral of traps, appraisals and exit interviews. She would rather trade than fight, but her definition of a fair trade is generous to Glintfang.","hooks":["Rob the hoard.","Trade with the dragon for a favour.","Rescue a merchant who got stuck in an exit interview."],"rumours":["She appraises everything, including you.","The hoard moves; she rearranges it daily.","Nobody leaves without signing something."],"wandering":{"die":"d6","entries":["1: A sandstorm sweeps the dune mouth","2: A kobold intern with a clipboard","3: A visitor in a tailored robe, who is Glintfang in disguise","4: A magic mirror asks the party's net worth","5: An appraiser's apprentice offers a quote","6: Distant gold coins rattling, as if the dragon is sleeping"]},"tropes":["Dragon's Hoard","Dragon","The Heist"],"author":"seth","status":"sample","entry":"tropelandia.room.glintfang-hoard.01-dune-mouth","rooms":[{"id":"tropelandia.room.glintfang-hoard.01-dune-mouth","number":1,"code":"DRG-01","name":"Dune Mouth","floor":0,"pos":[0,0],"light":"desert sun","size":"30 x 15 ft","exits":[{"dir":"s","to":"tropelandia.room.glintfang-hoard.02-sandstone-gallery","kind":"archway","state":"open","note":""},{"dir":"out","to":"outside","kind":"passage","state":"open","note":"The dunes"}],"readAloud":"A cleft in a towering dune opens into carved sandstone, its walls inscribed with a brass plaque: GLINTFANG & ASSOCIATES, EST. 612. PLEASE TAKE A NUMBER. A kobold in a waistcoat hands you a ticket stub that reads 'You are number 4,821'.","features":["The brass plaque","A kobold greeter","A wall of coins glittering in the sand"],"encounters":[{"name":"Kobold greeters","monsters":[{"name":"Kobold","count":3,"hp":5,"ac":12,"attack":"dagger +4, 1d4+2"}],"tactics":"They refuse entry until the party takes a ticket; combat only if shoved.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["A ticket stub (the party's place in the queue)"],"dmNotes":""},{"id":"tropelandia.room.glintfang-hoard.02-sandstone-gallery","number":2,"code":"DRG-02","name":"Sandstone Gallery","floor":0,"pos":[0,1],"light":"lamplight","size":"60 x 25 ft","exits":[{"dir":"n","to":"tropelandia.room.glintfang-hoard.01-dune-mouth","kind":"archway","state":"open","note":""},{"dir":"s","to":"tropelandia.room.glintfang-hoard.05-gilded-antechamber","kind":"archway","state":"open","note":""},{"dir":"e","to":"tropelandia.room.glintfang-hoard.03-hall-of-appraisals","kind":"door","state":"open","note":""},{"dir":"w","to":"tropelandia.room.glintfang-hoard.04-the-trapped-corridor","kind":"door","state":"open","note":""}],"readAloud":"A long hall of columns, each carved with the profile of a successful visitor who lost a portfolio. A runner of red carpet leads south. The floor tiles seem too clean. Somewhere a quill scratches.","features":["Columns of former visitors","A clean carpet","A quill scratching somewhere"],"encounters":[],"traps":[{"name":"Pressure tile","trigger":"Stepping off the carpet","effect":"Sandstone slabs: 4d6 bludgeoning, DC 14 Dex halves","detect_dc":15,"disarm_dc":14}],"puzzles":[],"secrets":[],"loot":[],"dmNotes":"The carpet is safe; the tiles aren't."},{"id":"tropelandia.room.glintfang-hoard.03-hall-of-appraisals","number":3,"code":"DRG-03","name":"Hall of Appraisals","floor":0,"pos":[1,1],"light":"mirrored glare","size":"40 x 40 ft","exits":[{"dir":"s","to":"tropelandia.room.glintfang-hoard.09-servants-quarters","kind":"door","state":"open","note":""},{"dir":"w","to":"tropelandia.room.glintfang-hoard.02-sandstone-gallery","kind":"door","state":"open","note":""}],"readAloud":"A grand hall of mirrors, each framing a different valuation: your weapons, your armour, your companions. A brass mechanical appraiser clicks and whirs, spitting out slips of paper that read 'LOW VALUE' on everything.","features":["A brass appraiser","Mirrors that value things","A stack of rejected slips"],"encounters":[{"name":"Mirror guardians","monsters":[{"name":"Mimic mirror","count":2,"hp":40,"ac":12,"attack":"bite +5, 2d6"}],"tactics":"Mirrors that copy the party's reflections attack on a failed appraisal.","treasure":""}],"traps":[],"puzzles":[{"name":"The Appraiser","description":"The brass appraiser is rigged; it values common things low and strange things high.","solution":"Offer it something unique (a story, a song, a lie) to get a favourable valuation.","hints":["It prefers novelty.","Describe an item as 'unique'.","The slips are in a code."],"reward":"A letter of introduction to Glintfang, which grants a better trade."}],"secrets":[],"loot":[],"dmNotes":""},{"id":"tropelandia.room.glintfang-hoard.04-the-trapped-corridor","number":4,"code":"DRG-04","name":"The Trapped Corridor","floor":0,"pos":[-1,1],"light":"dim","size":"10 x 60 ft","exits":[{"dir":"e","to":"tropelandia.room.glintfang-hoard.02-sandstone-gallery","kind":"door","state":"open","note":""}],"readAloud":"A narrow side corridor of polished sandstone, lined with alcoves of perfectly sized gold statues. A faint draught smells of oil. The floor is a mosaic of dull and bright tiles.","features":["Gold statues","A mosaic floor","A glint of wire"],"encounters":[],"traps":[{"name":"Statue crossfire","trigger":"Stepping on a bright tile","effect":"Statues fire darts: 3 x 2d6 piercing, DC 15 Dex halves","detect_dc":16,"disarm_dc":15},{"name":"Oil flood","trigger":"Stepping on a dull tile","effect":"Oil floods the corridor then ignites: 4d6 fire","detect_dc":15,"disarm_dc":14}],"puzzles":[],"secrets":[{"description":"A secret door at the end opens into a small store of gold","dc":17}],"loot":["Gold dust (worth 80 gp)"],"dmNotes":""},{"id":"tropelandia.room.glintfang-hoard.05-gilded-antechamber","number":5,"code":"DRG-05","name":"Gilded Antechamber","floor":0,"pos":[0,2],"light":"golden","size":"40 x 40 ft","exits":[{"dir":"n","to":"tropelandia.room.glintfang-hoard.02-sandstone-gallery","kind":"archway","state":"open","note":""},{"dir":"s","to":"tropelandia.room.glintfang-hoard.06-the-hoard","kind":"door","state":"open","note":""},{"dir":"e","to":"tropelandia.room.glintfang-hoard.09-servants-quarters","kind":"door","state":"open","note":""}],"readAloud":"A grand antechamber with a ceiling of beaten gold. A great desk stands at the end, where a woman in a tailored robe signs papers with a quill. She looks up, smiles with too many teeth and says, 'You must be the 4,821st. Do take a seat.'","features":["A golden desk","Chairs of beaten gold","A woman in a tailored robe"],"encounters":[{"name":"Glintfang in disguise","monsters":[{"name":"Glintfang (humanoid form, mage)","count":1,"hp":40,"ac":12,"attack":"dagger +4, 1d4+2; casts charm, suggestion"}],"tactics":"She is courteous. She wants a contract, not a fight. If the party attacks, she reveals her true form.","treasure":""}],"traps":[],"puzzles":[{"name":"The Contract","description":"Glintfang offers a trade: whatever the party wants, for a fee. The contract has fine print.","solution":"Read the fine print (Investigation DC 15) to avoid agreeing to indentured service.","hints":["She encourages signing quickly.","The clause on page 7 mentions 'exit fees'.","A magical reading reveals a hidden clause."],"reward":"A favourable trade."}],"secrets":[],"loot":[],"dmNotes":"Dragon's Hoard played as a negotiation: the dragon is a businesswoman."},{"id":"tropelandia.room.glintfang-hoard.06-the-hoard","number":6,"code":"DRG-06","name":"The Hoard","floor":0,"pos":[0,3],"light":"gold glare","size":"120 x 100 ft","exits":[{"dir":"n","to":"tropelandia.room.glintfang-hoard.05-gilded-antechamber","kind":"door","state":"open","note":""},{"dir":"e","to":"tropelandia.room.glintfang-hoard.07-treasury-annex","kind":"archway","state":"open","note":""},{"dir":"w","to":"tropelandia.room.glintfang-hoard.08-vault-of-returns","kind":"archway","state":"open","note":""}],"readAloud":"A cathedral-sized cavern, floor-to-ceiling gold, glittering like a sunrise in a coin-shaped sea. A young gold dragon the size of a barn coils atop it, one eye open, ledger floating in front of her. She says, 'Everything in here is for sale. Including you.'","features":["Coins in drifts","A floating ledger","Cleverly labelled piles: 'Swords', 'Crowns', 'Misc'"],"encounters":[{"name":"Glintfang","monsters":[{"name":"Glintfang (young gold dragon)","count":1,"hp":178,"ac":18,"attack":"bite +10, 2d10+6; fire breath 60 ft, 12d6"}],"tactics":"She fights only if robbed or insulted; she'll offer a trade first. In battle she uses her wings and breath, retreating into the coins.","treasure":""}],"traps":[{"name":"Coin avalanche","trigger":"Taking coins from the base of a pile","effect":"Coins slide: 4d6 bludgeoning, DC 14 Dex halves","detect_dc":14,"disarm_dc":0}],"puzzles":[],"secrets":[],"loot":["A portfolio of coins, gems and art (up to 20,000 gp if the party can carry it)"],"dmNotes":""},{"id":"tropelandia.room.glintfang-hoard.07-treasury-annex","number":7,"code":"DRG-07","name":"Treasury Annex","floor":0,"pos":[1,3],"light":"steady","size":"40 x 30 ft","exits":[{"dir":"w","to":"tropelandia.room.glintfang-hoard.06-the-hoard","kind":"archway","state":"open","note":""}],"readAloud":"A tidy room of shelves and numbered boxes, each filled with a single type of treasure: rings in one, crowns in another. A tiny dragon-sized stool sits before a ledger. A brass bell on the desk is labelled RING FOR SERVICE.","features":["Labelled boxes","A ledger","A service bell"],"encounters":[{"name":"Intern","monsters":[{"name":"Kobold accountant","count":2,"hp":5,"ac":12,"attack":"pen +3, 1d4"}],"tactics":"They sound the alarm if anyone takes an item without a receipt.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["A box of assorted gems (200 gp)","A box of rings (3 magic rings, DM's choice)"],"dmNotes":""},{"id":"tropelandia.room.glintfang-hoard.08-vault-of-returns","number":8,"code":"DRG-08","name":"Vault of Returns","floor":0,"pos":[-1,3],"light":"dim","size":"40 x 40 ft","exits":[{"dir":"e","to":"tropelandia.room.glintfang-hoard.06-the-hoard","kind":"archway","state":"open","note":""}],"readAloud":"A large, quiet room full of items marked with sticky notes: 'DID NOT FIT', 'WRONG COLOUR', 'CURSED (SORRY)'. A desk labelled COMPLAINTS stands unattended, with a bell and a stack of forms.","features":["Returned goods","A complaints desk","A pile of unclaimed cursed items"],"encounters":[],"traps":[],"puzzles":[],"secrets":[],"loot":["A cursed ring of Opinions","A returned sword that sulks","A bag of holding (slightly used)"],"dmNotes":"Cursed Item trope as retail: everything has a defect, and a cheerful receipt."},{"id":"tropelandia.room.glintfang-hoard.09-servants-quarters","number":9,"code":"DRG-09","name":"Servants' Quarters","floor":0,"pos":[1,2],"light":"lamplight","size":"40 x 30 ft","exits":[{"dir":"n","to":"tropelandia.room.glintfang-hoard.03-hall-of-appraisals","kind":"door","state":"open","note":""},{"dir":"w","to":"tropelandia.room.glintfang-hoard.05-gilded-antechamber","kind":"door","state":"open","note":""}],"readAloud":"A small warren of bedrooms and a mess hall where kobolds and a handful of enchanted statues play cards. A kobold shift supervisor with a clipboard looks up from a game and says, 'Are you the audit?'","features":["A card game","Bunk beds in rows","A shift roster"],"encounters":[{"name":"Off-duty staff","monsters":[{"name":"Kobold","count":6,"hp":5,"ac":12,"attack":"dagger +4, 1d4+2"}],"tactics":"Friendly unless threatened; they'll sell the party the layout of the hoard for a drink.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["A staff map (reveals the hoard's layout)"],"dmNotes":""}]},{"id":"tropelandia.dungeon.marlowes-tower","code":"TWR","name":"Marlowe's Tower","universe":"tropelandia","place":{"id":"tropelandia.settlement.barrowdale","name":"Barrowdale","path":["Tropelandia","Material Plane","Gleamhaven","Mildew Sun","Tropos","Mainland","Gently Haunted Marsh","Duchy of Mildew","Dampshire","Barrowdale"]},"levelRange":[3,5],"tone":"parody; tower-crawl","tags":["tower","wizard","vertical","traps","tropelandia-signature"],"summary":"A narrow tower of grey stone that appeared overnight during the Pie Contest Incident and has been 'temporarily' on the Mayor's judging table ever since. Marlowe the Mildly Menacing lives at the top, three months behind on rent, and defends it with a staircase, a rule about footwear, and a lot of glassware.","hooks":["Burgle the tower while Marlowe is out.","Apprentice yourself to Marlowe (and learn his rent troubles).","Deliver a legal notice to the top floor."],"rumours":["The tower is smaller on the outside than inside, and the Mayor will not discuss this.","Marlowe keeps a rival's secret recipe in his study.","Nobody has seen him leave in a month; someone has seen the milk delivery though."],"wandering":{"die":"d6","entries":["1: A sheet of paper flutters down the stairwell: an eviction notice","2: A floating broom drifts by, sweeping with great resentment","3: The stairs shuffle themselves (re-roll direction)","4: A flying inkpot attacks, then apologises","5: A magical rodent scuttles past, carrying a note","6: Distant shouting: 'WHO PUT THE ROOF ON THE JUDGES' TABLE?'"]},"tropes":["Wizard in a Tower","Mimic","Cursed Item"],"author":"seth","status":"sample","entry":"tropelandia.room.marlowes-tower.01-entrance-hall","rooms":[{"id":"tropelandia.room.marlowes-tower.01-entrance-hall","number":1,"code":"TWR-01","name":"Entrance Hall","floor":0,"pos":[0,0],"light":"floating candles","size":"25 ft diameter","exits":[{"dir":"e","to":"tropelandia.room.marlowes-tower.02-wizards-kitchen","kind":"door","state":"open","note":""},{"dir":"u","to":"tropelandia.room.marlowes-tower.03-the-library","kind":"stairs","state":"open","note":"The spiral stair; it rearranges itself behind you"},{"dir":"d","to":"tropelandia.room.marlowes-tower.08-the-basement-laboratory","kind":"hatch","state":"locked","note":"Iron trapdoor; DC 15 lock; or the key in the kitchen"},{"dir":"out","to":"outside","kind":"door","state":"open","note":"The tower door onto Barrowdale's judging table"}],"readAloud":"A round hall with a floor of black and white tiles, lit by candles that float at head height. A staircase spirals upward; a smaller door leads east and a trapdoor in the floor leads down. A sign on the wall reads: PLEASE REMOVE BOOTS. DO NOT TOUCH THE BANISTER. DO NOT ASK ABOUT THE FLOOR. The banister hums.","features":["Floating candles","A boot rack with exactly one pair of very large shoes","A banister that gives a mild shock"],"encounters":[{"name":"Welcome broom","monsters":[{"name":"Animated broom (flying sword stats)","count":1,"hp":17,"ac":17,"attack":"slam +3, 1d6+1"}],"tactics":"It tries to remove the party's boots, and fights if refused; it can be bribed with a nice polish.","treasure":""}],"traps":[{"name":"Banister shock","trigger":"Touching the banister","effect":"DC 12 Con save or 2d6 lightning and a hairstyle","detect_dc":11,"disarm_dc":12}],"puzzles":[],"secrets":[],"loot":[],"dmNotes":"Establishes tone. Wizard in a Tower beat: the tower tests visitors with a staircase and a rule."},{"id":"tropelandia.room.marlowes-tower.02-wizards-kitchen","number":2,"code":"TWR-02","name":"Wizard's Kitchen","floor":0,"pos":[1,0],"light":"firelit","size":"20 x 15 ft","exits":[{"dir":"w","to":"tropelandia.room.marlowes-tower.01-entrance-hall","kind":"door","state":"open","note":""}],"readAloud":"A cluttered kitchen with a cauldron that is clearly the main appliance. Pots stir themselves; a skeleton in an apron is making what might be soup. A rack of keys hangs by the door, labelled: PANTRY, CELLAR, ROOF, 'NOT THE CELLAR', and 'DEFINITELY NOT THE ROOF'.","features":["A self-stirring cauldron of soup","A skeleton in an apron (Gerald)","The key rack"],"encounters":[{"name":"Gerald the cook","monsters":[{"name":"Skeleton cook","count":1,"hp":13,"ac":13,"attack":"ladle +4, 1d6+2"}],"tactics":"Gerald will serve the party soup and ask them to leave; he fights only if the soup is insulted.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["The cellar key","A pot of healing soup (restores 1d8 HP)","Marlowe's overdue rent notices (11)"],"dmNotes":"The soup is genuinely nourishing; the skeleton is a good-natured cook who wants a day off."},{"id":"tropelandia.room.marlowes-tower.03-the-library","number":3,"code":"TWR-03","name":"The Library","floor":1,"pos":[0,0],"light":"dim","size":"35 ft diameter","exits":[{"dir":"n","to":"tropelandia.room.marlowes-tower.04-the-study-of-mild-menace","kind":"door","state":"closed","note":""},{"dir":"u","to":"tropelandia.room.marlowes-tower.05-apprentices-quarters","kind":"stairs","state":"open","note":""},{"dir":"d","to":"tropelandia.room.marlowes-tower.01-entrance-hall","kind":"stairs","state":"open","note":"The spiral stair; it rearranges itself behind you"}],"readAloud":"Shelves climb the walls to a vaulted ceiling lost in shadow, every one packed with books, scrolls and what appears to be a large collection of takeaway menus. A ladder on wheels glides along a rail on its own, trailing a trail of dust. A small plaque reads: SILENCE, PLEASE. THE BOOKS ARE LISTENING.","features":["A wheeled ladder with a mind of its own","Takeaway menus from six planes","A reading chair that tilts toward interesting books"],"encounters":[],"traps":[{"name":"Paper cuts","trigger":"Shouting or loud noise","effect":"Pages cut: 2d6 slashing in a 15 ft cone, DC 13 Dex halves","detect_dc":12,"disarm_dc":13}],"puzzles":[{"name":"The Shushing Shelves","description":"A bookshelf in the north wall hides the study door. The books whisper hints about the door's password if the party speaks quietly. Speak too loudly and the books attack with paper cuts.","solution":"Whisper the password 'overdue' (clue: 'a library's greatest sin') to the books; the shelf swings open.","hints":["Books whisper when you whisper.","The word is something every library fears.","The menus have a clue: a late fee."],"reward":"The shelf opens to the study."}],"secrets":[],"loot":["A scroll of Feather Fall tucked in a menu","A first-edition Guide to Reasonable Rent"],"dmNotes":"Light puzzle, quick to solve; the library is the trope's first obstacle."},{"id":"tropelandia.room.marlowes-tower.04-the-study-of-mild-menace","number":4,"code":"TWR-04","name":"The Study of Mild Menace","floor":1,"pos":[0,-1],"light":"warm","size":"20 x 15 ft","exits":[{"dir":"s","to":"tropelandia.room.marlowes-tower.03-the-library","kind":"door","state":"closed","note":""}],"readAloud":"A comfortable room dominated by a desk, a stuffed owl and a cluster of trophy-case pies. A framed certificate on the wall reads: WINNER, BARROWDALE PIE CONTEST, 1489 (DISPUTED). A pie sits on the desk, steaming, with a note: DO NOT EAT. IT IS A TRAP. IT IS ALSO DELICIOUS.","features":["The disputed trophy cabinet","A stuffed owl that watches","The Pie of Mild Menace (a trap)"],"encounters":[{"name":"Stuffed owl guardian","monsters":[{"name":"Owl (animated)","count":1,"hp":22,"ac":13,"attack":"talons +4, 1d6+2"}],"tactics":"Attacks if the pie is stolen or the trophy touched.","treasure":""}],"traps":[{"name":"The Pie","trigger":"Eating the pie","effect":"DC 14 Con save or 3d6 poison and hiccups for an hour; on a success, advantage on checks for the next hour","detect_dc":13,"disarm_dc":0}],"puzzles":[],"secrets":[{"description":"A false drawer in the desk holds a letter from Dame Rosalind: 'Your pie was good. I hate you.'","dc":14}],"loot":["The disputed pie trophy (worth 50 gp, worth a lot more to Rosalind)","Marlowe's private recipe for blackberry pie","A signed IOU from the Mayor"],"dmNotes":"The Pie Contest Incident is a canon event; this study can reflect it. Marlowe's grudges here are nemesis-system fodder."},{"id":"tropelandia.room.marlowes-tower.05-apprentices-quarters","number":5,"code":"TWR-05","name":"Apprentice's Quarters","floor":2,"pos":[0,0],"light":"grey daylight","size":"20 x 15 ft","exits":[{"dir":"e","to":"tropelandia.room.marlowes-tower.06-the-bath-of-unexpected-destinations","kind":"door","state":"open","note":""},{"dir":"u","to":"tropelandia.room.marlowes-tower.07-the-observatory","kind":"stairs","state":"open","note":""},{"dir":"d","to":"tropelandia.room.marlowes-tower.03-the-library","kind":"stairs","state":"open","note":""}],"readAloud":"A cramped bedroom on the third floor with a single bed, a desk and a bucket labelled MINE. A series of increasingly desperate letters is pinned to the walls, each one signed with a different name and each one resigning. A single spare apprentice robe hangs on a hook, two sizes too small.","features":["The resignation letters","An unusually well-kept bed","A sign: BE QUIET, MASTER IS SULKING"],"encounters":[{"name":"Overworked apprentice","monsters":[{"name":"Apprentice (acolyte stats)","count":1,"hp":9,"ac":10,"attack":"staff +2, 1d6"}],"tactics":"Not hostile; wants a change. Might join the party if the party offers a better salary.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["A robe of useful items (as Robe of Useful Items, with only rent receipts in the patches)"],"dmNotes":"Wizard in a Tower hook: the party can be recruited as the next apprentice."},{"id":"tropelandia.room.marlowes-tower.06-the-bath-of-unexpected-destinations","number":6,"code":"TWR-06","name":"The Bath of Unexpected Destinations","floor":2,"pos":[1,0],"light":"steam","size":"15 x 15 ft","exits":[{"dir":"w","to":"tropelandia.room.marlowes-tower.05-apprentices-quarters","kind":"door","state":"open","note":""}],"readAloud":"A steamy bathroom with a large copper tub and a curtain. Each tap labelled HOT, COLD and MISC. The water in the tub swirls slowly and shows the reflection of somewhere that is not this room: a beach, a market, an unfamiliar mountain.","features":["The portal tub","Three taps","Rubber duck (enchanted)"],"encounters":[],"traps":[{"name":"Scalding steam","trigger":"Opening the HOT tap fully","effect":"2d6 fire in the room, DC 13 Con save halves","detect_dc":12,"disarm_dc":0}],"puzzles":[{"name":"The Taps","description":"Turning the MISC tap sends whoever steps into the tub to a random location on Tropos. HOT sends them to a hot place, COLD to a cold place.","solution":"Set HOT and COLD in sequence to open a stable portal to the Barrowdale town square.","hints":["The taps change the destination.","Mixing two properties gives a middle place.","The duck squeaks a hint: 'town'."],"reward":"A safe return to town, or an excuse for a side adventure."}],"secrets":[],"loot":[],"dmNotes":"A fun exit for a party that has had enough; also a way to bring in side quests."},{"id":"tropelandia.room.marlowes-tower.07-the-observatory","number":7,"code":"TWR-07","name":"The Observatory","floor":3,"pos":[0,0],"light":"starlight and lanterns","size":"30 ft diameter","exits":[{"dir":"d","to":"tropelandia.room.marlowes-tower.05-apprentices-quarters","kind":"stairs","state":"open","note":""}],"readAloud":"The top of the tower opens into a round glass-domed room full of brass telescopes and star charts. A grand desk occupies the centre, where Marlowe the Mildly Menacing sits wearing a pointed hat and an expression of tragic dignity. He looks up, sighs, and says, 'It's about the rent, isn't it.'","features":["A brass orrery that predicts rent due dates","The Wizard's Desk","An unpaid rent notice nailed to the telescope"],"encounters":[{"name":"Marlowe","monsters":[{"name":"Marlowe the Mildly Menacing (mage)","count":1,"hp":40,"ac":12,"attack":"firebolt +6, 2d10; spells: fireball, counterspell, misty step"}],"tactics":"He fights only if the party attempts to take the tower's key artefact, or insults his pie. Prefers a bribe, a reasonable rent plan, or a good apprentice.","treasure":""}],"traps":[],"puzzles":[{"name":"The Rent Problem","description":"Marlowe will help the party if they solve his rent problem. He owes 3 months to the Mayor.","solution":"Find 90 gp (via the strongbox in the cellar, the trophy, or by negotiating with the Mayor).","hints":["He keeps looking at the orrery.","The Mayor wants a favour more than money.","The trophy might fetch a price from Rosalind."],"reward":"A powerful ally, a scroll of choice, and a nemesis grudge softened."}],"secrets":[],"loot":["A wand of mild magic missiles","Marlowe's pointed hat (cursed: you cannot take it off, and people think you're funnier)"],"dmNotes":"Marlowe is a Wizard in a Tower, played straight: sympathetic, trapped by money. His grudge with Rosalind is nemesis-system material."},{"id":"tropelandia.room.marlowes-tower.08-the-basement-laboratory","number":8,"code":"TWR-08","name":"The Basement Laboratory","floor":-1,"pos":[0,0],"light":"green glow","size":"35 x 25 ft","exits":[{"dir":"u","to":"tropelandia.room.marlowes-tower.01-entrance-hall","kind":"hatch","state":"locked","note":"Iron trapdoor; DC 15 lock; or the key in the kitchen"}],"readAloud":"A cold, dank cellar converted into a laboratory, lined with bubbling beakers, jars of preserved things and a large iron vat that glows green. A faint chanting comes from the vat. A hand-written sign says: WHAT ARE YOU DOING DOWN HERE? THIS IS AN EXPERIMENT.","features":["The glowing vat","Jars of preserved things","A cage of confused magical rabbits"],"encounters":[{"name":"Experiment gone wrong","monsters":[{"name":"Ooze (green slime vat)","count":1,"hp":45,"ac":8,"attack":"pseudopod +5, 2d6 acid"}],"tactics":"The ooze attacks anyone who stirs the vat; it can be calmed with flour (Marlowe's kitchen).","treasure":""}],"traps":[{"name":"Volatile vial","trigger":"Handling the beakers carelessly","effect":"A vial explodes: DC 13 Dex save or 3d6 fire in 10 ft","detect_dc":14,"disarm_dc":13}],"puzzles":[],"secrets":[],"loot":["A potion of growth","A potion of hair restoration","Marlowe's secret: a copy of the unpaid dragon bill from the pantry"],"dmNotes":"Where Marlowe hides his experiments. The ooze is a small boss for a low-level party."}]},{"id":"tropelandia.dungeon.cellar-of-rats","code":"RAT","name":"The Cellar of Rats","universe":"tropelandia","place":{"id":"tropelandia.settlement.barrowdale","name":"Barrowdale","path":["Tropelandia","Material Plane","Gleamhaven","Mildew Sun","Tropos","Mainland","Gently Haunted Marsh","Duchy of Mildew","Dampshire","Barrowdale"]},"levelRange":[1,2],"tone":"gentle parody","tags":["tutorial","urban","rats","negotiation"],"summary":"The cellar of the Gilded Tankard inn, Barrowdale's most reliable source of rodents. The innkeeper has posted the same job notice for nine years: ten rats, two silver pieces. The rats have noticed the notice, and have views.","hooks":["Take the innkeeper's job and clear out the rats.","Find out why the rats are so organised.","Recover the stock the innkeeper swears he never lost."],"rumours":["The rats have been seen carrying tiny notices.","Nobody who went down came back with ten rats; they came back with an opinion.","The innkeeper has not been down there in nine years, and keeps changing the subject."],"wandering":{"die":"d6","entries":["1: 1d4 rats scurry past carrying a tiny crate","2: A distant squeak, followed by a very small cheer","3: A rat pauses, reads the party's boots, and leaves","4: 2 giant rats, hungry (hp 7, AC 12)","5: The innkeeper's boy, sent to check on the party, bearing cheese","6: Nothing; the dark seems smug"]},"tropes":["Kill Ten Rats","The Tavern Where It All Starts","Goblins as Fodder"],"author":"seth","status":"sample","entry":"tropelandia.room.cellar-of-rats.01-cellar-stairs","rooms":[{"id":"tropelandia.room.cellar-of-rats.01-cellar-stairs","number":1,"code":"RAT-01","name":"Cellar Stairs","floor":0,"pos":[0,0],"light":"dim (hanging lantern)","size":"10 x 10 ft","exits":[{"dir":"s","to":"tropelandia.room.cellar-of-rats.02-barrel-hall","kind":"archway","state":"open","note":""},{"dir":"u","to":"outside","kind":"stairs","state":"open","note":"Up to the Gilded Tankard's kitchen"}],"readAloud":"Twelve stone steps drop into a cold that smells of old wine, wet stone and something furry. A lantern hangs from a hook, its flame trembling at every squeak from below. The step at the bottom is worn into a hollow, as though a great many small feet have been using it.","features":["A hook with a spare lantern","A hand-lettered sign: DANGER (RATS) (ALSO STAIRS)","Chalk tally marks on the wall, nine years of them"],"encounters":[],"traps":[],"puzzles":[],"secrets":[],"loot":[],"dmNotes":"Quiet start. The squeaking is audible here; make the party feel watched, not attacked."},{"id":"tropelandia.room.cellar-of-rats.02-barrel-hall","number":2,"code":"RAT-02","name":"Barrel Hall","floor":0,"pos":[0,1],"light":"dim","size":"30 x 20 ft","exits":[{"dir":"n","to":"tropelandia.room.cellar-of-rats.01-cellar-stairs","kind":"archway","state":"open","note":""},{"dir":"s","to":"tropelandia.room.cellar-of-rats.06-the-warren","kind":"passage","state":"open","note":""},{"dir":"e","to":"tropelandia.room.cellar-of-rats.03-cold-pantry","kind":"door","state":"stuck","note":"Swollen with damp (DC 12 Str)"},{"dir":"w","to":"tropelandia.room.cellar-of-rats.04-wine-racks","kind":"archway","state":"open","note":""}],"readAloud":"A long, low hall lined with barrels on their sides, each stamped with the inn's gilded tankard. Water drips in a slow rhythm from the vaulted ceiling. Between the barrels, small shapes dart from shadow to shadow.","features":["Barrels, some empty, some not","A hand cart with a broken wheel","Rat droppings in neat rows"],"encounters":[{"name":"Rat patrol","monsters":[{"name":"Giant rat","count":4,"hp":7,"ac":12,"attack":"bite +4, 1d4+2"}],"tactics":"Rats dart out from behind the barrels and try to split the party; they flee when two are killed, and tell the Rat King.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["A single silver piece, wedged under a barrel"],"dmNotes":"If the party leaves a rat alive, it reports to the Rat King; the throne room encounter begins with a lookout."},{"id":"tropelandia.room.cellar-of-rats.03-cold-pantry","number":3,"code":"RAT-03","name":"Cold Pantry","floor":0,"pos":[1,1],"light":"dim","size":"15 x 15 ft","exits":[{"dir":"w","to":"tropelandia.room.cellar-of-rats.02-barrel-hall","kind":"door","state":"stuck","note":"Swollen with damp (DC 12 Str)"}],"readAloud":"A cold room with iron hooks hanging from the ceiling, empty except for a single wheel of cheese on a stand, glistening faintly and smelling strongly of regret. A trail of crumbs leads to the wall behind it.","features":["The Wheel of Cheese, bait for a trap","Iron hooks","A ham, long past eating"],"encounters":[],"traps":[{"name":"Falling portcullis net","trigger":"Lifting the cheese from its stand","effect":"A weighted net drops: DC 12 Dex save or restrained; rats swarm in 1d4 rounds","detect_dc":13,"disarm_dc":12}],"puzzles":[],"secrets":[{"description":"A loose stone behind the hooks hides the innkeeper's lost strongbox: 35 gp and an unpaid bill of sale for a dragon","dc":14}],"loot":["35 gp in the strongbox","A very good ham"],"dmNotes":"Cheese is a Cursed Item joke: it's non-magical, but the rats believe it is."},{"id":"tropelandia.room.cellar-of-rats.04-wine-racks","number":4,"code":"RAT-04","name":"Wine Racks","floor":0,"pos":[-1,1],"light":"dim","size":"25 x 15 ft","exits":[{"dir":"s","to":"tropelandia.room.cellar-of-rats.05-collapsed-tunnel","kind":"passage","state":"rubble","note":"Choked with fallen stone; crawl only"},{"dir":"e","to":"tropelandia.room.cellar-of-rats.02-barrel-hall","kind":"archway","state":"open","note":""}],"readAloud":"Floor-to-ceiling wine racks stretch into the gloom, most of them smashed. A drift of glass and sticky stains runs toward the south wall, where the floor tilts into a gap. Something has been drinking here, and has left a very small bottle of excellent vintage on the floor.","features":["Smashed racks","A tiny, immaculate bottle of vintage wine","A trail of paw prints through the glass"],"encounters":[{"name":"Wine thief","monsters":[{"name":"Giant rat","count":2,"hp":7,"ac":12,"attack":"bite +4, 1d4+2"},{"name":"Rat Sommelier","count":1,"hp":9,"ac":13,"attack":"bite +4, 1d4+2 (disadvantage if the party is rude about the wine)"}],"tactics":"The sommelier tries to bargain; refuse and it signals the rest.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["A bottle of fine wine worth 25 gp"],"dmNotes":""},{"id":"tropelandia.room.cellar-of-rats.05-collapsed-tunnel","number":5,"code":"RAT-05","name":"Collapsed Tunnel","floor":0,"pos":[-1,2],"light":"dim","size":"10 x 40 ft, 3 ft high","exits":[{"dir":"n","to":"tropelandia.room.cellar-of-rats.04-wine-racks","kind":"passage","state":"rubble","note":"Choked with fallen stone; crawl only"},{"dir":"e","to":"tropelandia.room.cellar-of-rats.06-the-warren","kind":"passage","state":"rubble","note":"Crawl, no armour above light"}],"readAloud":"A section of old brick tunnel, half-buried by a cave-in, runs east. The only way through is a low crawl over broken masonry. You can hear small voices ahead, arguing in a language that is mostly squeaks and one very clear word: 'rent'.","features":["Loose masonry","A rat-sized bridge over a puddle","Scratched graffiti: RATS LIVES MATTER"],"encounters":[],"traps":[{"name":"Rubble slide","trigger":"Moving through without care","effect":"Rubble slides: DC 11 Dex save or 1d6 bludgeoning and stuck for 1d4 rounds","detect_dc":12,"disarm_dc":10}],"puzzles":[],"secrets":[],"loot":[],"dmNotes":"Small characters crawl through; Medium characters take a round to squeeze."},{"id":"tropelandia.room.cellar-of-rats.06-the-warren","number":6,"code":"RAT-06","name":"The Warren","floor":0,"pos":[0,2],"light":"dim","size":"40 x 30 ft","exits":[{"dir":"n","to":"tropelandia.room.cellar-of-rats.02-barrel-hall","kind":"passage","state":"open","note":""},{"dir":"s","to":"tropelandia.room.cellar-of-rats.07-the-rat-kings-pantry","kind":"passage","state":"open","note":""},{"dir":"w","to":"tropelandia.room.cellar-of-rats.05-collapsed-tunnel","kind":"passage","state":"rubble","note":"Crawl, no armour above light"}],"readAloud":"A cavernous space under the inn's old foundations, carved by generations of rats into a tangled warren. Nests of shredded paper, cheese rind and bottle caps fill every nook. A hundred glittering eyes follow your every step.","features":["Nests of paper and cloth","A pile of bottle caps (currency)","A tiny wooden notice board with a listing: ONE (1) RAT NEEDED, WILL TRAIN"],"encounters":[{"name":"Rat horde","monsters":[{"name":"Giant rat","count":8,"hp":7,"ac":12,"attack":"bite +4, 1d4+2"},{"name":"Swarm of rats","count":1,"hp":24,"ac":10,"attack":"bites +2, 2d6 (half when below half HP)"}],"tactics":"The horde fights to protect the throne; they hold if the party parleys with a bribe (cheese or coin), and will not attack anyone carrying the Cheese Wheel.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["120 sp scattered through the nests","A tiny silver crown, too small for a human head"],"dmNotes":"Parley is a real option: if the party speaks or acts reasonably, rats will bring them to the Rat King."},{"id":"tropelandia.room.cellar-of-rats.07-the-rat-kings-pantry","number":7,"code":"RAT-07","name":"The Rat King's Pantry","floor":0,"pos":[0,3],"light":"candles","size":"20 x 20 ft","exits":[{"dir":"n","to":"tropelandia.room.cellar-of-rats.06-the-warren","kind":"passage","state":"open","note":""}],"readAloud":"A cosy, absurdly furnished chamber lined with stolen thimbles, buttons and one enormous gold ring. At its heart sits the Rat King, a swollen rat in a tiny crown wearing the innkeeper's lost spectacles, upon a throne made of nine years of unpaid bills. It looks up, adjusts the spectacles, and says, in a voice too large for its body, 'You're late.'","features":["The Throne of Bills","A hoard of thimbles, buttons and cheese","The innkeeper's spectacles"],"encounters":[{"name":"The Rat King","monsters":[{"name":"Rat King (giant rat, Cunning)","count":1,"hp":22,"ac":12,"attack":"bite +4, 1d6+2"},{"name":"Giant rat guard","count":4,"hp":7,"ac":12,"attack":"bite +4, 1d4+2"}],"tactics":"He'd prefer to talk. He wants a lower rent (the inn charges him 1 cheese/day), a place on the inn's council, and the nine-year notice taken down. If attacked, his guards fight to the death; he flees through a hole in the wall.","treasure":""}],"traps":[],"puzzles":[{"name":"The Negotiation","description":"The Rat King negotiates: he will leave the cellar if the party gets the innkeeper to meet three demands: a seat at the inn's table, a cheese tax cut, and the notice removed.","solution":"Accept his demands (Persuasion DC 12) and report back to the innkeeper (DC 14 to convince him), or defeat him in combat.","hints":["He keeps mentioning 'the notice'.","The spectacles are not just for show; he reads the bills.","Speaking to him as an equal changes his attitude two steps."],"reward":"The inn's gratitude, a free room for a month, and a lasting friendly rat contact."}],"secrets":[],"loot":["A huge gold ring (worth 60 gp), actually the innkeeper's wife's wedding band","The spectacles"],"dmNotes":"Gentle subversion of Kill Ten Rats: the ten-rat notice is a joke about bureaucracy. A sweet ending is on offer; the party can still choose violence."}]},{"id":"tropelandia.dungeon.dwarven-folly","code":"DWF","name":"The Dwarven Folly","universe":"tropelandia","place":{"id":"tropelandia.region.crooked-peaks","name":"Crooked Peaks","path":["Tropelandia","Material Plane","Gleamhaven","Mildew Sun","Tropos","Mainland","Crooked Peaks"]},"levelRange":[5,7],"tone":"grim parody","tags":["mine","dwarves","underground","ancient-evil","forge"],"summary":"Karak-Dum-Dum was the proudest dwarven hold in the Crooked Peaks, right up to the day its miners dug a little too deep. The upper halls are still impressive, the forge still sings, and something below has been politely knocking for three hundred years.","hooks":["Reclaim the lost halls for the surviving clan.","Find out what the dwarves dug into.","Recover the Anvil of Opinions, a legendary forge."],"rumours":["The forge sings at midnight; the song has a second voice.","Every miner who went down came back with a cough and a secret.","The dwarves left their beer. A dwarf does not leave beer."],"wandering":{"die":"d6","entries":["1: Distant hammering, three beats, stop","2: 1d4 duergar scouts, arguing about a map","3: A cold wind from below, smelling of old stone and something wrong","4: A cave-in (DC 13 Dex or 2d6)","5: A lost miner's ghost asks for a hat","6: Silence, which in a dwarven hall is itself a warning"]},"tropes":["Dwarven Mine","Grumpy Ale-Loving Dwarf","Ancient Evil Released by Dumb Adventurers"],"author":"seth","status":"sample","entry":"tropelandia.room.dwarven-folly.01-the-gatehouse","rooms":[{"id":"tropelandia.room.dwarven-folly.01-the-gatehouse","number":1,"code":"DWF-01","name":"The Gatehouse","floor":0,"pos":[0,0],"light":"daylight fading","size":"40 x 20 ft","exits":[{"dir":"s","to":"tropelandia.room.dwarven-folly.02-the-great-hall","kind":"archway","state":"open","note":""},{"dir":"out","to":"outside","kind":"door","state":"open","note":"The mountain path"}],"readAloud":"Twin stone doors, three storeys tall, stand ajar in the mountainside, carved with rank upon rank of stern dwarven kings. A guardhouse flanks them, its door off its hinges. A banner reads KARAK-DUM-DUM: OPEN 9 TO 5 (CLOSED INDEFINITELY).","features":["Carved dwarf kings","A broken guardhouse","A mounted skeleton of a dwarf with a pike"],"encounters":[{"name":"Rusty watch","monsters":[{"name":"Animated armor","count":2,"hp":33,"ac":18,"attack":"slam +4, 2d6+2"}],"tactics":"The gate's armour wakes when anyone crosses without announcing themselves.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["A dwarven battle standard worth 30 gp"],"dmNotes":""},{"id":"tropelandia.room.dwarven-folly.02-the-great-hall","number":2,"code":"DWF-02","name":"The Great Hall","floor":0,"pos":[0,1],"light":"dim, from high windows","size":"80 x 50 ft","exits":[{"dir":"n","to":"tropelandia.room.dwarven-folly.01-the-gatehouse","kind":"archway","state":"open","note":""},{"dir":"s","to":"tropelandia.room.dwarven-folly.05-the-singing-forge","kind":"archway","state":"open","note":""},{"dir":"e","to":"tropelandia.room.dwarven-folly.03-the-brewery","kind":"door","state":"open","note":""},{"dir":"w","to":"tropelandia.room.dwarven-folly.04-the-barracks","kind":"door","state":"open","note":""}],"readAloud":"A hall of vast pillars, each carved with a dwarven king, supports a ceiling that vanishes in dark. Long tables, thick with dust, stretch to a dais bearing an empty throne. Hanging banners hang in tatters, and a draught from the south carries a faint, steady, sorrowful humming.","features":["Kingly pillars","The throne of Karak-Dum-Dum","Mouldering banners"],"encounters":[{"name":"Dwarf specters","monsters":[{"name":"Specter","count":2,"hp":22,"ac":12,"attack":"life drain +4, 3d6"}],"tactics":"They appear if the throne is sat upon; they'll demand the party's names, then ask them to leave.","treasure":""}],"traps":[],"puzzles":[],"secrets":[{"description":"A hidden compartment in the throne holds a rolled map of the lower tunnels","dc":15}],"loot":["The map of the lower tunnels (reduces getting lost in the shaft)"],"dmNotes":""},{"id":"tropelandia.room.dwarven-folly.03-the-brewery","number":3,"code":"DWF-03","name":"The Brewery","floor":0,"pos":[1,1],"light":"dim","size":"40 x 30 ft","exits":[{"dir":"w","to":"tropelandia.room.dwarven-folly.02-the-great-hall","kind":"door","state":"open","note":""}],"readAloud":"Copper vats the size of cottages loom out of the gloom, their sides green with age. The air is sweet and heavy, and a faint bubbling suggests that some of them are still fermenting. A hand-painted sign says: THE LAST BATCH. DO NOT.","features":["Copper vats","A tap marked 'dwarven spirit'","A stained notebook of recipes"],"encounters":[],"traps":[{"name":"Fermentation burst","trigger":"Opening the wrong vat","effect":"Foul gas: DC 14 Con save or poisoned for 1 hour","detect_dc":13,"disarm_dc":12}],"puzzles":[],"secrets":[],"loot":["Barrel of The Last Batch (a mind-bending ale, worth 100 gp to the right dwarf)","The brewmaster's recipe (valuable)"],"dmNotes":"The Last Batch is a Cursed Item: whoever drinks it gains Darkvision and Strong Opinions for a day."},{"id":"tropelandia.room.dwarven-folly.04-the-barracks","number":4,"code":"DWF-04","name":"The Barracks","floor":0,"pos":[-1,1],"light":"dim","size":"50 x 30 ft","exits":[{"dir":"e","to":"tropelandia.room.dwarven-folly.02-the-great-hall","kind":"door","state":"open","note":""}],"readAloud":"Rows of bunks stretch into the dark, each topped with a neatly folded blanket and a tin cup. A rack of axes gleams in the dust. In the far corner a lone dwarf in full armour sits upright on a bunk, motionless, a half-eaten loaf of stone-bread in one hand.","features":["Neat bunks","An axe rack","A seated dwarf, unmoving"],"encounters":[{"name":"The Last Sentry","monsters":[{"name":"Dwarven revenant","count":1,"hp":60,"ac":16,"attack":"greataxe +6, 1d12+4"}],"tactics":"He rises if anyone sits on his bunk; he can be calmed by returning the Banner from the gatehouse.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["Dwarven axes (3, worth 15 gp each)","A tin cup engraved with a name"],"dmNotes":""},{"id":"tropelandia.room.dwarven-folly.05-the-singing-forge","number":5,"code":"DWF-05","name":"The Singing Forge","floor":0,"pos":[0,2],"light":"forge glow","size":"60 x 40 ft","exits":[{"dir":"n","to":"tropelandia.room.dwarven-folly.02-the-great-hall","kind":"archway","state":"open","note":""},{"dir":"d","to":"tropelandia.room.dwarven-folly.06-the-mine-shaft","kind":"stairs","state":"open","note":"A wide ramp into the mine shaft"}],"readAloud":"A vast forge chamber ringing with the sound of a distant hammer. The anvil, a block of black iron the size of a wagon, glows faintly red. The sound is not a hammer after all, but a voice: low, patient, singing in a tongue that makes your teeth ache.","features":["The Anvil of Opinions","A crucible of cold molten metal","A bellows that breathes by itself"],"encounters":[{"name":"Fire spirits","monsters":[{"name":"Fire elemental (minor)","count":2,"hp":20,"ac":13,"attack":"touch +4, 2d6 fire"}],"tactics":"They erupt from the crucible if the song is interrupted.","treasure":""}],"traps":[],"puzzles":[{"name":"The Anvil's Song","description":"The anvil sings three notes; the party must answer with the same three on the nearby chimes.","solution":"Strike the chimes in order: low, high, middle.","hints":["The song repeats.","The chimes are labelled.","The notes spell a dwarven name."],"reward":"The forge goes silent for an hour; the shaft is safe to descend."}],"secrets":[],"loot":["Anvil of Opinions (artifact; talks, offers advice)"],"dmNotes":""},{"id":"tropelandia.room.dwarven-folly.06-the-mine-shaft","number":6,"code":"DWF-06","name":"The Mine Shaft","floor":-1,"pos":[0,2],"light":"swaying lanterns","size":"40 ft diameter, 200 ft deep","exits":[{"dir":"s","to":"tropelandia.room.dwarven-folly.07-the-fungus-caverns","kind":"passage","state":"open","note":""},{"dir":"u","to":"tropelandia.room.dwarven-folly.05-the-singing-forge","kind":"stairs","state":"open","note":""}],"readAloud":"A vast vertical shaft plunges into darkness, a spiral ramp winding down its walls. Lanterns on chains sway in the updraft. The air smells of wet stone and ancient things. Old mine carts sit abandoned on tracks that end in thin air.","features":["Mine carts on broken rails","A rope bridge","Scratched warnings in dwarven"],"encounters":[],"traps":[{"name":"Rotten bridge","trigger":"Crossing the rope bridge","effect":"DC 13 Dex save or fall 30 ft (3d6)","detect_dc":12,"disarm_dc":0}],"puzzles":[],"secrets":[],"loot":[],"dmNotes":""},{"id":"tropelandia.room.dwarven-folly.07-the-fungus-caverns","number":7,"code":"DWF-07","name":"The Fungus Caverns","floor":-1,"pos":[0,3],"light":"bioluminescent","size":"60 x 50 ft","exits":[{"dir":"n","to":"tropelandia.room.dwarven-folly.06-the-mine-shaft","kind":"passage","state":"open","note":""},{"dir":"s","to":"tropelandia.room.dwarven-folly.09-the-breach","kind":"passage","state":"closed","note":"A fresh-dug tunnel"},{"dir":"e","to":"tropelandia.room.dwarven-folly.08-the-underground-lake","kind":"passage","state":"open","note":""}],"readAloud":"A cavern of luminous mushrooms, some tall as trees, bathes the stone in sickly blue and green. Spores drift through the air like snow. Between the stalks, a lumbering shape sways, humming along with the faraway song.","features":["Giant mushrooms","A glowing spore cloud","A duergar camp, abandoned"],"encounters":[{"name":"Shriekers and myconids","monsters":[{"name":"Shrieker","count":2,"hp":13,"ac":5,"attack":"shriek"},{"name":"Myconid sovereign","count":1,"hp":60,"ac":10,"attack":"fist +4, 1d6+2"}],"tactics":"Shriekers alert duergar nearby; the myconid is friendly if offered rare minerals.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["Rare mushrooms (potions)","Duergar supplies"],"dmNotes":""},{"id":"tropelandia.room.dwarven-folly.08-the-underground-lake","number":8,"code":"DWF-08","name":"The Underground Lake","floor":-1,"pos":[1,3],"light":"dark","size":"80 x 60 ft","exits":[{"dir":"w","to":"tropelandia.room.dwarven-folly.07-the-fungus-caverns","kind":"passage","state":"open","note":""}],"readAloud":"A still black lake fills a vaulted cavern, its surface dotted with the roofs of drowned dwarven buildings. A narrow stone causeway crosses the water. Something very large moves slowly beneath the surface.","features":["The causeway","Drowned buildings","A boat tied to a post"],"encounters":[{"name":"Lake guardian","monsters":[{"name":"Giant octopus","count":1,"hp":52,"ac":11,"attack":"tentacles +5, 2d6+3"}],"tactics":"It attacks anyone on the causeway who splashes; it can be bargained with using fish.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["A drowned dwarven vault (50 gp and a gem)"],"dmNotes":""},{"id":"tropelandia.room.dwarven-folly.09-the-breach","number":9,"code":"DWF-09","name":"The Breach","floor":-1,"pos":[0,4],"light":"unnatural","size":"20 x 30 ft","exits":[{"dir":"n","to":"tropelandia.room.dwarven-folly.07-the-fungus-caverns","kind":"passage","state":"closed","note":"A fresh-dug tunnel"},{"dir":"s","to":"tropelandia.room.dwarven-folly.10-the-thing-they-dug-into","kind":"portal","state":"open","note":"A hole in the rock"}],"readAloud":"A rough-hewn tunnel, newer than the rest, ends in a ragged hole in the rock. Beyond it lies a chamber of impossible geometry: stone that is not stone, angles that hurt to look at. A voice speaks from the hole: 'Hello? Are you the plumber?'","features":["The knocking hole","Strange stone","Duergar corpses with serene smiles"],"encounters":[],"traps":[{"name":"Mind-bending geometry","trigger":"Staring into the hole","effect":"DC 14 Wis save or stunned for 1 round","detect_dc":13,"disarm_dc":0}],"puzzles":[],"secrets":[],"loot":[],"dmNotes":""},{"id":"tropelandia.room.dwarven-folly.10-the-thing-they-dug-into","number":10,"code":"DWF-10","name":"The Thing They Dug Into","floor":-1,"pos":[0,5],"light":"unnatural","size":"100 x 100 ft","exits":[{"dir":"n","to":"tropelandia.room.dwarven-folly.09-the-breach","kind":"portal","state":"open","note":"A hole in the rock"}],"readAloud":"A vast, shifting chamber of black glass and pulsing veins. A being the size of a house floats at its centre, many-eyed and patient, wearing a tiny name tag that reads 'HELLO, MY NAME IS ...' The tag is smudged. The being smiles with something that is not a mouth.","features":["A being wearing a name tag","A floor of black glass","Pulsing veins in the walls"],"encounters":[{"name":"The Plumber","monsters":[{"name":"Elder Thing (aberration)","count":1,"hp":135,"ac":15,"attack":"tentacles +8, 3d6 psychic"}],"tactics":"Not hostile at first; it wants someone to fix the leak it came in through. If refused it attacks.","treasure":""}],"traps":[],"puzzles":[{"name":"The Repair Job","description":"The being has a leak in the wall between worlds and needs a skilled crafter to patch it.","solution":"A DC 15 Smith's Tools check, or the Anvil of Opinions' advice, patches the leak.","hints":["The being keeps looking at a hole.","It offers a tool.","The anvil sings a repair song."],"reward":"The being rewards the party with a boon and goes home."}],"secrets":[],"loot":["A gift from beyond (a wish-adjacent boon, DM's choice)"],"dmNotes":"Ancient Evil Released by Dumb Adventurers, inverted: the evil isn't evil, just stranded. Keep it weird and polite."}]},{"id":"tropelandia.dungeon.goblin-union-hall","code":"GOB","name":"The Goblin Union Hall","universe":"tropelandia","place":{"id":"tropelandia.region.whisperwood","name":"Whisperwood","path":["Tropelandia","Material Plane","Gleamhaven","Mildew Sun","Tropos","Mainland","Whisperwood"]},"levelRange":[1,3],"tone":"workplace comedy","tags":["goblins","negotiation","union","forest","social-encounter"],"summary":"A hollow oak in Whisperwood, the headquarters of Local 7 of the United Brotherhood of Goblins, Hobs and Allied Skulkers. They are on strike. The picket line has not moved in six weeks, and neither has the management. They would very much like someone to mediate, and are prepared to attack anyone who is not them.","hooks":["Mediate the strike.","Cross the picket line.","Find out what the goblins actually want."],"rumours":["The Union has a strike fund and a grudge.","The Hobgoblin Foreman has not slept in six days.","The Boss is a very short man in a very long coat."],"wandering":{"die":"d6","entries":["1: Pickets chanting: 'WHAT DO WE WANT? BREAK ROOM!'","2: A goblin hands the party a flyer","3: A scab (a squirrel) scurries through","4: 3 angry goblins (hp 7, AC 15)","5: A tired hobgoblin asks for a mediator","6: A long, uneasy silence; someone coughs"]},"tropes":["Goblins as Fodder","Village Menaced by Goblins","Tavern Brawl"],"author":"seth","status":"sample","entry":"tropelandia.room.goblin-union-hall.01-the-picket-line","rooms":[{"id":"tropelandia.room.goblin-union-hall.01-the-picket-line","number":1,"code":"GOB-01","name":"The Picket Line","floor":0,"pos":[0,0],"light":"dappled sun","size":"40 x 40 ft","exits":[{"dir":"s","to":"tropelandia.room.goblin-union-hall.02-reception","kind":"door","state":"closed","note":"Blocked by pickets"},{"dir":"out","to":"outside","kind":"passage","state":"open","note":"The forest road"}],"readAloud":"A hollow oak, three storeys tall, rises out of the forest floor. A ring of goblins marches in circles outside it, carrying signs: UNFAIR TO GOBLINS, MORE MUSHROOMS, NO MORE DOOMED RAIDS. They look at the party with the weary dignity of the underpaid.","features":["Picketing goblins","Hand-lettered signs","A brazier of mushroom soup"],"encounters":[{"name":"Picketers","monsters":[{"name":"Goblin","count":6,"hp":7,"ac":15,"attack":"scimitar +4, 1d6+2"}],"tactics":"They fight if the party crosses the line without talking; they'll let a mediator pass.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":[],"dmNotes":"Wins by talking. Violence is the long way round."},{"id":"tropelandia.room.goblin-union-hall.02-reception","number":2,"code":"GOB-02","name":"Reception","floor":0,"pos":[0,1],"light":"candlelight","size":"30 x 20 ft","exits":[{"dir":"n","to":"tropelandia.room.goblin-union-hall.01-the-picket-line","kind":"door","state":"closed","note":"Blocked by pickets"},{"dir":"s","to":"tropelandia.room.goblin-union-hall.05-the-main-floor","kind":"archway","state":"open","note":""},{"dir":"e","to":"tropelandia.room.goblin-union-hall.03-the-break-room","kind":"door","state":"open","note":""},{"dir":"w","to":"tropelandia.room.goblin-union-hall.04-grievance-office","kind":"door","state":"open","note":""}],"readAloud":"A cramped reception carved from the heart of the tree. A goblin receptionist with a pencil behind her ear sits behind a desk labelled 'GRIEVANCES, PLEASE TAKE A NUMBER'. A wall of forms, stamped and filed, shows all the things the goblins want.","features":["A reception desk","A wall of forms","A queue of waiting goblins"],"encounters":[{"name":"Receptionist","monsters":[{"name":"Goblin receptionist","count":1,"hp":7,"ac":15,"attack":"pencil +4, 1d4+2"}],"tactics":"She wants the party to fill out Form 27B. Refusing gets a stern lecture.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":[],"dmNotes":"Social encounter: be polite, be patient, bring forms."},{"id":"tropelandia.room.goblin-union-hall.03-the-break-room","number":3,"code":"GOB-03","name":"The Break Room","floor":0,"pos":[1,1],"light":"warm","size":"20 x 20 ft","exits":[{"dir":"s","to":"tropelandia.room.goblin-union-hall.06-the-workshop","kind":"door","state":"open","note":""},{"dir":"w","to":"tropelandia.room.goblin-union-hall.02-reception","kind":"door","state":"open","note":""}],"readAloud":"A small break room with a chipped table, a kettle that has been boiling for six weeks and a bulletin board reading: BREAK ROOM NEEDS A WINDOW. A few exhausted goblins slump around the table, nursing mugs of fungus tea.","features":["A chipped table","A permanent kettle","A bulletin board of demands"],"encounters":[{"name":"Tired workers","monsters":[{"name":"Goblin","count":3,"hp":7,"ac":15,"attack":"scimitar +4, 1d6+2"}],"tactics":"Not hostile; they want a deal. Happy to talk.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["A mug of fungus tea (restores 1d4 HP)","A list of union demands"],"dmNotes":""},{"id":"tropelandia.room.goblin-union-hall.04-grievance-office","number":4,"code":"GOB-04","name":"Grievance Office","floor":0,"pos":[-1,1],"light":"lamplight","size":"25 x 20 ft","exits":[{"dir":"s","to":"tropelandia.room.goblin-union-hall.07-the-strike-fund","kind":"door","state":"locked","note":"Union lock; key held by Grimble"},{"dir":"e","to":"tropelandia.room.goblin-union-hall.02-reception","kind":"door","state":"open","note":""}],"readAloud":"A tidy office with filing cabinets and a desk piled with complaints. A hobgoblin in a sash sorts through them, muttering. The nameplate reads: SHOP STEWARD GRIMBLE. A poster behind him reads 'SOLIDARITY (OR ELSE)'.","features":["Filing cabinets","A pile of grievances","Grimble's sash of office"],"encounters":[{"name":"Shop Steward Grimble","monsters":[{"name":"Hobgoblin shop steward","count":1,"hp":11,"ac":18,"attack":"longsword +3, 1d8+1"}],"tactics":"Grimble listens if the party addresses him correctly and hands him a petition; he fights if insulted.","treasure":""}],"traps":[],"puzzles":[{"name":"The Petition","description":"Grimble demands three concessions on paper before he'll open the strike fund vault.","solution":"Draft a petition promising a window in the break room, a fair wage, and safer raids (Persuasion DC 12).","hints":["He keeps looking at the break room.","He mentions 'doomed raids'.","Pay is the third demand."],"reward":"Grimble grants the vault key."}],"secrets":[],"loot":["The strike fund key"],"dmNotes":""},{"id":"tropelandia.room.goblin-union-hall.05-the-main-floor","number":5,"code":"GOB-05","name":"The Main Floor","floor":0,"pos":[0,2],"light":"firelit","size":"60 x 50 ft","exits":[{"dir":"n","to":"tropelandia.room.goblin-union-hall.02-reception","kind":"archway","state":"open","note":""},{"dir":"s","to":"tropelandia.room.goblin-union-hall.08-the-chiefs-office","kind":"door","state":"open","note":""},{"dir":"e","to":"tropelandia.room.goblin-union-hall.06-the-workshop","kind":"archway","state":"open","note":""},{"dir":"w","to":"tropelandia.room.goblin-union-hall.07-the-strike-fund","kind":"archway","state":"open","note":""}],"readAloud":"A cavernous chamber carved from the oak's heart, with tiers of rough benches, a speaker's podium and hundreds of goblins in angry attendance. At the podium stands a goblin in a bowler hat addressing the crowd with growing force. The crowd goes silent when you enter.","features":["Rough benches","A podium","An angry crowd"],"encounters":[{"name":"Mass meeting","monsters":[{"name":"Goblin","count":12,"hp":7,"ac":15,"attack":"scimitar +4, 1d6+2"}],"tactics":"The crowd turns hostile if the party makes threats; a rousing speech (Persuasion DC 14) can turn them into allies.","treasure":""}],"traps":[],"puzzles":[{"name":"The Speech","description":"The party can win over the meeting with a good speech, a vote, or a promise.","solution":"Persuasion/Performance DC 14 with a concession from the list of demands.","hints":["Their demands are posted.","The crowd cheers certain words.","A promise of mushrooms works."],"reward":"The crowd cheers and backs the party; the Chief becomes willing to deal."}],"secrets":[],"loot":[],"dmNotes":""},{"id":"tropelandia.room.goblin-union-hall.06-the-workshop","number":6,"code":"GOB-06","name":"The Workshop","floor":0,"pos":[1,2],"light":"lamplight","size":"35 x 25 ft","exits":[{"dir":"n","to":"tropelandia.room.goblin-union-hall.03-the-break-room","kind":"door","state":"open","note":""},{"dir":"w","to":"tropelandia.room.goblin-union-hall.05-the-main-floor","kind":"archway","state":"open","note":""}],"readAloud":"A noisy workshop of benches and half-built contraptions: crude traps, rope ladders, a trebuchet made from a wheelbarrow. The goblins have put down tools but left everything in place. A foreman's whistle hangs from a hook.","features":["Half-built traps","A wheelbarrow trebuchet","A foreman's whistle"],"encounters":[],"traps":[{"name":"Tripwire","trigger":"Walking through without looking","effect":"A bundle of spikes drops: 2d6 piercing, DC 12 Dex halves","detect_dc":12,"disarm_dc":11}],"puzzles":[],"secrets":[],"loot":["Goblin trap parts (worth 25 gp)","A foreman's whistle (calls goblins to order)"],"dmNotes":""},{"id":"tropelandia.room.goblin-union-hall.07-the-strike-fund","number":7,"code":"GOB-07","name":"The Strike Fund","floor":0,"pos":[-1,2],"light":"dim","size":"15 x 15 ft","exits":[{"dir":"n","to":"tropelandia.room.goblin-union-hall.04-grievance-office","kind":"door","state":"locked","note":"Union lock; key held by Grimble"},{"dir":"e","to":"tropelandia.room.goblin-union-hall.05-the-main-floor","kind":"archway","state":"open","note":""}],"readAloud":"A small vault lined with iron plates. A heavy chest sits in the centre, locked with three separate padlocks. A scrap of paper on the lid reads: STRIKE FUND: DO NOT SPEND ON MUSHROOMS.","features":["A triple-locked chest","Iron plated walls","A union ledger"],"encounters":[],"traps":[],"puzzles":[],"secrets":[],"loot":["Strike fund (450 gp)","A ledger showing the fund has been used for mushrooms (it has)"],"dmNotes":"A moral wrinkle: the fund is theirs. Taking it makes the party scabs and thieves."},{"id":"tropelandia.room.goblin-union-hall.08-the-chiefs-office","number":8,"code":"GOB-08","name":"The Chief's Office","floor":0,"pos":[0,3],"light":"warm lamplight","size":"25 x 20 ft","exits":[{"dir":"n","to":"tropelandia.room.goblin-union-hall.05-the-main-floor","kind":"door","state":"open","note":""}],"readAloud":"A small, tidy office. Behind a vast desk sits a figure in a bowler hat and a too-large coat, seemingly three goblins stacked on each other's shoulders. 'Welcome to Local 7,' says the top one. 'Please excuse the coat. We are in a transitional period.'","features":["A huge desk","A long coat with suspicious bulges","A framed charter of the union"],"encounters":[{"name":"The Chief (three goblins in a coat)","monsters":[{"name":"Goblin","count":3,"hp":7,"ac":15,"attack":"scimitar +4, 1d6+2"}],"tactics":"They'd rather negotiate. If attacked, the coat falls apart and the goblins scatter.","treasure":""}],"traps":[],"puzzles":[{"name":"The Deal","description":"The strike can be settled with a deal: a window, a better wage and an end to doomed raids.","solution":"A negotiation (Persuasion DC 13) using the demands collected during the dungeon.","hints":["Collect the demands.","Everyone wants something different.","The coat's other occupant has a secret."],"reward":"The strike ends, the party gets the union's gratitude and a stipend of mushrooms."}],"secrets":[],"loot":["A bowler hat (the Chief's)","Union membership card (grants favours from goblins)"],"dmNotes":"Goblins as Fodder subverted: they are people with grievances, and the best ending is a deal."}]},{"id":"tropelandia.dungeon.guildhall-below","code":"GLD","name":"The Guildhall Below","universe":"tropelandia","place":{"id":"tropelandia.region.sullen-coast","name":"Sullen Coast","path":["Tropelandia","Material Plane","Gleamhaven","Mildew Sun","Tropos","Mainland","Sullen Coast"]},"levelRange":[3,5],"tone":"caper parody","tags":["thieves","city","heist","stealth","guild"],"summary":"Beneath the Port Pilferage fish market sits the Guildhall of the Honourable Society of Independent Acquisitionists, a thieves' guild with a dress code, a membership fee and a vault that has never, officially, been robbed. The party's job is either to join, rob or inspect it. The guild would rather they chose joining.","hooks":["Rob the guild's vault.","Join the guild (and survive initiation).","Retrieve something stolen from a client."],"rumours":["Everyone in Port Pilferage is a member, or owes one.","The Guildmaster's parlour has a back exit that is also a front exit.","The vault door is a riddle, and so is the key."],"wandering":{"die":"d6","entries":["1: Two thieves argue about commission","2: A pickpocket attempts the party (DC 13 Perception)","3: A guard asks to see membership cards","4: A forger offers a good price on 'certificates'","5: The lights flicker; someone has pawned the generator","6: A cat that is probably a spy watches from a ledge"]},"tropes":["Thieves' Guild","The Heist","Quest Giver Betrays the Party"],"author":"seth","status":"sample","entry":"tropelandia.room.guildhall-below.01-the-fishmongers-stall","rooms":[{"id":"tropelandia.room.guildhall-below.01-the-fishmongers-stall","number":1,"code":"GLD-01","name":"The Fishmonger's Stall","floor":0,"pos":[0,0],"light":"harbour daylight","size":"15 x 10 ft","exits":[{"dir":"d","to":"tropelandia.room.guildhall-below.02-the-smelly-cellar","kind":"hatch","state":"closed","note":"A false-bottomed barrel; the fishmonger's password: 'perch'"},{"dir":"out","to":"outside","kind":"door","state":"open","note":"The market"}],"readAloud":"A reeking stall in the Port Pilferage fish market, its counter laden with slick silver fish. A fishmonger in a bloody apron eyes you with practised suspicion and taps a barrel that sounds oddly hollow. A handwritten sign says: FRESH FISH. FRESHER PRICES. NO QUESTIONS.","features":["A stall of fish","A false barrel","A lookout fishmonger"],"encounters":[{"name":"Fishmonger","monsters":[{"name":"Thug","count":1,"hp":32,"ac":11,"attack":"mace +4, 1d6+2"}],"tactics":"He asks for the password; the wrong one earns a fish to the face.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["A very large fish"],"dmNotes":"The password is learnable from Rosa the street kid or by bribing the fishmonger."},{"id":"tropelandia.room.guildhall-below.02-the-smelly-cellar","number":2,"code":"GLD-02","name":"The Smelly Cellar","floor":-1,"pos":[0,0],"light":"lantern glow","size":"30 x 20 ft","exits":[{"dir":"s","to":"tropelandia.room.guildhall-below.03-the-hall-of-moots","kind":"door","state":"open","note":""},{"dir":"u","to":"tropelandia.room.guildhall-below.01-the-fishmongers-stall","kind":"hatch","state":"closed","note":"A false-bottomed barrel; the fishmonger's password: 'perch'"}],"readAloud":"A flooded cellar of old fish barrels and sagging crates. A ladder drops into water; a line of hooks hangs from the ceiling, each with a lantern. Beyond a rotted door, voices and the clink of coin carry through the stink.","features":["Old barrels","Lanterns on hooks","A trail of footprints"],"encounters":[{"name":"Lookouts","monsters":[{"name":"Bandit","count":2,"hp":11,"ac":12,"attack":"scimitar +3, 1d6+1"}],"tactics":"They ask for the sign (a particular whistle) and attack if not given.","treasure":""}],"traps":[{"name":"Slippery floor","trigger":"Running across the wet floor","effect":"DC 12 Dex save or fall prone, 1d4 damage","detect_dc":12,"disarm_dc":0}],"puzzles":[],"secrets":[],"loot":[],"dmNotes":""},{"id":"tropelandia.room.guildhall-below.03-the-hall-of-moots","number":3,"code":"GLD-03","name":"The Hall of Moots","floor":-1,"pos":[0,1],"light":"lamplight","size":"60 x 50 ft","exits":[{"dir":"n","to":"tropelandia.room.guildhall-below.02-the-smelly-cellar","kind":"door","state":"open","note":""},{"dir":"s","to":"tropelandia.room.guildhall-below.06-vault-corridor","kind":"archway","state":"open","note":""},{"dir":"e","to":"tropelandia.room.guildhall-below.04-the-fences-counter","kind":"door","state":"open","note":""},{"dir":"w","to":"tropelandia.room.guildhall-below.05-the-trap-gym","kind":"door","state":"open","note":""}],"readAloud":"A great vaulted chamber that was once a smuggler's cavern, now a guild meeting hall. Benches, a raised dais, and a mural of the guild's history: a long row of thieves taking things from other thieves. A bell hangs over the dais for calling members to order.","features":["A dais and bell","A mural","A noticeboard of jobs"],"encounters":[{"name":"Guild members at leisure","monsters":[{"name":"Bandit","count":6,"hp":11,"ac":12,"attack":"scimitar +3, 1d6+1"},{"name":"Spy","count":2,"hp":27,"ac":12,"attack":"shortsword +4, 1d6+2"}],"tactics":"They are not hostile unless the party is caught stealing.","treasure":""}],"traps":[],"puzzles":[{"name":"The Moot","description":"The guild may hold a moot to decide whether the party is trusted. A party member must give a short speech.","solution":"Persuasion/Deception DC 14; bring a reference from Rosa.","hints":["The guild loves a good heist story.","Name-drop someone useful.","Brag politely."],"reward":"Guild membership and access to the vault corridor."}],"secrets":[],"loot":[],"dmNotes":""},{"id":"tropelandia.room.guildhall-below.04-the-fences-counter","number":4,"code":"GLD-04","name":"The Fence's Counter","floor":-1,"pos":[1,1],"light":"lantern","size":"25 x 20 ft","exits":[{"dir":"s","to":"tropelandia.room.guildhall-below.07-the-guildmasters-parlour","kind":"door","state":"open","note":""},{"dir":"w","to":"tropelandia.room.guildhall-below.03-the-hall-of-moots","kind":"door","state":"open","note":""}],"readAloud":"A shabby counter with a wire cage and a small lantern. Behind it sits a wiry fence with an eyepiece, surrounded by shelves of other people's property. 'Everything's a bargain,' she says, 'if you don't ask where it's from.'","features":["A wire cage counter","Shelves of stolen goods","A ledger of provenance"],"encounters":[{"name":"The Fence","monsters":[{"name":"Spy","count":1,"hp":27,"ac":12,"attack":"dagger +4, 1d4+2"}],"tactics":"She sells and buys. She fights only if the party tries to rob her counter.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["Stolen goods (sell for 100 gp)","A forged guild membership card"],"dmNotes":""},{"id":"tropelandia.room.guildhall-below.05-the-trap-gym","number":5,"code":"GLD-05","name":"The Trap Gym","floor":-1,"pos":[-1,1],"light":"lanterns","size":"50 x 30 ft","exits":[{"dir":"s","to":"tropelandia.room.guildhall-below.08-the-counterfeit-press","kind":"door","state":"open","note":""},{"dir":"e","to":"tropelandia.room.guildhall-below.03-the-hall-of-moots","kind":"door","state":"open","note":""}],"readAloud":"A long training hall with an obstacle course of trapped corridors, tripwires and swinging blades. A sign on the wall reads: INITIATES ONLY. NO LIABILITY. A rack of wooden practice weapons lies untouched.","features":["A trap obstacle course","Practice weapons","A scoreboard of best times"],"encounters":[],"traps":[{"name":"The Gauntlet","trigger":"Running the obstacle course","effect":"Three traps in sequence; DC 13 Dex each, 2d6 damage on failure","detect_dc":13,"disarm_dc":12}],"puzzles":[],"secrets":[],"loot":[],"dmNotes":"The course can be used for the initiation test."},{"id":"tropelandia.room.guildhall-below.06-vault-corridor","number":6,"code":"GLD-06","name":"Vault Corridor","floor":-1,"pos":[0,2],"light":"bright","size":"50 x 15 ft","exits":[{"dir":"n","to":"tropelandia.room.guildhall-below.03-the-hall-of-moots","kind":"archway","state":"open","note":""},{"dir":"s","to":"tropelandia.room.guildhall-below.09-the-guild-vault","kind":"door","state":"locked","note":"Vault door (see Guild Vault)"},{"dir":"e","to":"tropelandia.room.guildhall-below.07-the-guildmasters-parlour","kind":"door","state":"open","note":""},{"dir":"w","to":"tropelandia.room.guildhall-below.08-the-counterfeit-press","kind":"door","state":"open","note":""}],"readAloud":"A broad corridor leads away from the moot hall, its walls inlaid with copper threads and its floor a chessboard of black and white tiles. At the end, a great vault door glints. A sign reads: GUILD PROPERTY. PLEASE DO NOT STEAL.","features":["Copper-threaded walls","A chessboard floor","A vault door"],"encounters":[],"traps":[{"name":"Chessboard floor","trigger":"Stepping on the wrong colour","effect":"Walls shoot darts: 2d6 piercing, DC 14 Dex halves","detect_dc":15,"disarm_dc":14}],"puzzles":[],"secrets":[],"loot":[],"dmNotes":"Safe path: follow the knight's move pattern (clue in the Moot mural)."},{"id":"tropelandia.room.guildhall-below.07-the-guildmasters-parlour","number":7,"code":"GLD-07","name":"The Guildmaster's Parlour","floor":-1,"pos":[1,2],"light":"firelit","size":"30 x 25 ft","exits":[{"dir":"n","to":"tropelandia.room.guildhall-below.04-the-fences-counter","kind":"door","state":"open","note":""},{"dir":"w","to":"tropelandia.room.guildhall-below.06-vault-corridor","kind":"door","state":"open","note":""}],"readAloud":"A cosy, elegant room with deep armchairs, a roaring fire and shelves of leather-bound ledgers. A graceful old woman in a velvet gown pours tea. 'Do sit down,' says the Guildmaster. 'I've been expecting you. I always expect everyone.'","features":["Armchairs and tea","Ledgers","A map of the entire city's valuables"],"encounters":[{"name":"The Guildmaster","monsters":[{"name":"Assassin (retired)","count":1,"hp":78,"ac":15,"attack":"poisoned dagger +6, 3d6+3"}],"tactics":"She prefers conversation; she offers the party a job, and a trap.","treasure":""}],"traps":[],"puzzles":[{"name":"The Offer","description":"The Guildmaster proposes a job: steal something from a rival. It's a test and a trap.","solution":"Accept and plan carefully; or ask good questions (Insight DC 15) to learn it's a trap.","hints":["She offers too much money.","The target is her own vault.","The guild loves loyalty."],"reward":"Guild favour and a lucrative contract."}],"secrets":[],"loot":["Tea (a very fine blend, 20 gp)","A guild ring (opens guild doors)"],"dmNotes":""},{"id":"tropelandia.room.guildhall-below.08-the-counterfeit-press","number":8,"code":"GLD-08","name":"The Counterfeit Press","floor":-1,"pos":[-1,2],"light":"bright lamps","size":"35 x 25 ft","exits":[{"dir":"n","to":"tropelandia.room.guildhall-below.05-the-trap-gym","kind":"door","state":"open","note":""},{"dir":"e","to":"tropelandia.room.guildhall-below.06-vault-corridor","kind":"door","state":"open","note":""}],"readAloud":"A printing room full of presses, plates and stacks of paper. Fresh sheets of currency hang to dry like laundry. A team of forgers works silently, wearing green visors.","features":["Printing presses","Drying currency","Plates of seals and signatures"],"encounters":[{"name":"Forgers","monsters":[{"name":"Commoner forger","count":4,"hp":4,"ac":10,"attack":"pen +2, 1d4"}],"tactics":"They flee and call the guards if disturbed.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["Forged documents (useful)","Counterfeit currency (risky, 200 gp face value)"],"dmNotes":""},{"id":"tropelandia.room.guildhall-below.09-the-guild-vault","number":9,"code":"GLD-09","name":"The Guild Vault","floor":-1,"pos":[0,3],"light":"dim","size":"40 x 30 ft","exits":[{"dir":"n","to":"tropelandia.room.guildhall-below.06-vault-corridor","kind":"door","state":"locked","note":"Vault door (see Guild Vault)"}],"readAloud":"A hushed vault of shelves and safes, lined with steel. In the centre stands a single pedestal holding a plain wooden box. A brass plaque: THE GUILD'S MOST VALUABLE POSSESSION. A smaller sign: IT'S EMPTY. WE KNOW YOU WERE LOOKING.","features":["A pedestal and box","Rows of safes","A mocking plaque"],"encounters":[],"traps":[{"name":"Pedestal alarm","trigger":"Lifting the box","effect":"A siren sounds and the doors lock; DC 15 Dex to slip out before the guards arrive","detect_dc":16,"disarm_dc":15}],"puzzles":[{"name":"The Vault Door","description":"The vault door has no lock; it's a riddle on a plaque: 'The more you take, the more you leave behind.'","solution":"Say 'footsteps' aloud.","hints":["It's a riddle.","You're taking something with you.","Walking."],"reward":"The door opens."}],"secrets":[],"loot":["The real treasure is in the safes: 600 gp and 3 gems","The box is empty, apart from a note: 'Better luck next time'"],"dmNotes":"Quest Giver Betrays the Party: the Guildmaster wanted the party to try, to test the vault's defences."}]},{"id":"tropelandia.dungeon.lichs-filing-office","code":"LCH","name":"The Lich's Filing Office","universe":"tropelandia","place":{"id":"tropelandia.region.hollow-deep","name":"Hollow Deep","path":["Tropelandia","Material Plane","Gleamhaven","Mildew Sun","Tropos","The Underside","Hollow Deep"]},"levelRange":[10,12],"tone":"bureaucratic horror comedy","tags":["lich","bureaucracy","undead","high-level","underworld"],"summary":"In the Hollow Deep, beneath the world, sits the Office of Eternal Records: a vast bureaucracy run by Lord Vexmort the Undying, who found immortality easy and paperwork impossible. Every soul he has ever bound is filed here, in triplicate. Heroes come to destroy him. His secretary has asked that they take a number.","hooks":["Destroy the lich's phylactery.","Retrieve a soul from the files.","File a complaint about a particular death."],"rumours":["The lich has not left his desk in 900 years.","The phylactery is somewhere in the filing system.","The waiting room has no exit."],"wandering":{"die":"d6","entries":["1: A skeletal clerk hands the party a form","2: A queue forms behind the party","3: A bell rings; a 15-minute coffee break is declared","4: A ghostly auditor arrives","5: A stamp falls from the ceiling (2d6)","6: A distant voice: 'WHO LOST THE FILE?'"]},"tropes":["Lich","Dark Lord","Villain Monologue"],"author":"seth","status":"sample","entry":"tropelandia.room.lichs-filing-office.01-reception","rooms":[{"id":"tropelandia.room.lichs-filing-office.01-reception","number":1,"code":"LCH-01","name":"Reception","floor":0,"pos":[0,0],"light":"cold blue","size":"40 x 30 ft","exits":[{"dir":"s","to":"tropelandia.room.lichs-filing-office.02-the-waiting-hall","kind":"archway","state":"open","note":""},{"dir":"out","to":"outside","kind":"door","state":"open","note":"The cavern road"}],"readAloud":"A black marble foyer with a desk the size of a coffin. A skeleton in a neat cravat looks up from a ledger. 'Welcome to the Office of Eternal Records,' it says. 'Do you have an appointment? Do you have a death certificate? Please take a number.' A glowing sign reads: NOW SERVING 9,114,203.","features":["A coffin-sized desk","A skeleton receptionist","A ticket dispenser"],"encounters":[{"name":"Receptionist","monsters":[{"name":"Skeleton clerk","count":1,"hp":13,"ac":13,"attack":"stamp +4, 1d6+2"}],"tactics":"It insists on forms. It can be bribed with a stamp.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["A ticket stub (number 9,114,204)"],"dmNotes":""},{"id":"tropelandia.room.lichs-filing-office.02-the-waiting-hall","number":2,"code":"LCH-02","name":"The Waiting Hall","floor":0,"pos":[0,1],"light":"dim","size":"100 x 60 ft","exits":[{"dir":"n","to":"tropelandia.room.lichs-filing-office.01-reception","kind":"archway","state":"open","note":""},{"dir":"s","to":"tropelandia.room.lichs-filing-office.05-the-records-hall","kind":"archway","state":"open","note":""},{"dir":"e","to":"tropelandia.room.lichs-filing-office.03-the-forms-desk","kind":"door","state":"open","note":""},{"dir":"w","to":"tropelandia.room.lichs-filing-office.04-the-inbox","kind":"door","state":"open","note":""}],"readAloud":"A vast hall of benches stretches into the dark, where hundreds of ghostly petitioners wait in silence, clutching forms. A distant clock ticks, and the hands do not move. A sign says: YOUR CALL IS IMPORTANT TO US.","features":["Endless benches","Ghostly petitioners","A clock that doesn't move"],"encounters":[{"name":"Ghost queue","monsters":[{"name":"Ghost","count":4,"hp":45,"ac":11,"attack":"withering touch +5, 4d6 (only if line-cutters)"}],"tactics":"They attack anyone who skips the queue.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":[],"dmNotes":"Queue-cutting is the way to start a fight. Politeness is the way to avoid it."},{"id":"tropelandia.room.lichs-filing-office.03-the-forms-desk","number":3,"code":"LCH-03","name":"The Forms Desk","floor":0,"pos":[1,1],"light":"green lamp","size":"30 x 25 ft","exits":[{"dir":"s","to":"tropelandia.room.lichs-filing-office.06-phylactery-storage","kind":"door","state":"open","note":""},{"dir":"w","to":"tropelandia.room.lichs-filing-office.02-the-waiting-hall","kind":"door","state":"open","note":""}],"readAloud":"A desk piled with stacks of paper, towering and teetering. A clerk with a green eyeshade stamps forms in a rhythmic, mindless blur. Behind him, a pneumatic tube sucks forms into the walls.","features":["Stacks of forms","A pneumatic tube","A stamp pad"],"encounters":[{"name":"Clerk","monsters":[{"name":"Lich's clerk (specter)","count":1,"hp":22,"ac":12,"attack":"stamp +4, 3d6 necrotic"}],"tactics":"He attacks if the party is rude or unreasonable.","treasure":""}],"traps":[],"puzzles":[{"name":"The Form","description":"To progress, the party must fill out Form 27B in triplicate. The clerk will only accept it if the answers are coherent.","solution":"Fill the form out correctly (Investigation DC 15) or forge the signature (Deception DC 16).","hints":["The form has a hidden field.","Boxes marked 'Cause of death'.","The clerk loves spelling errors."],"reward":"The clerk stamps the form; the door opens."}],"secrets":[],"loot":[],"dmNotes":""},{"id":"tropelandia.room.lichs-filing-office.04-the-inbox","number":4,"code":"LCH-04","name":"The Inbox","floor":0,"pos":[-1,1],"light":"dim","size":"40 x 40 ft","exits":[{"dir":"s","to":"tropelandia.room.lichs-filing-office.07-appeals","kind":"door","state":"open","note":""},{"dir":"e","to":"tropelandia.room.lichs-filing-office.02-the-waiting-hall","kind":"door","state":"open","note":""}],"readAloud":"A mountain of unopened letters fills the room, drifting like snow. A pair of shades sort envelopes with ghostly hands. A sign reads: URGENT. ALSO URGENT. ALSO URGENT. In the middle, a chute marked 'To the Lich' hums.","features":["A mountain of mail","Sorting shades","A chute to the Lich"],"encounters":[{"name":"Mail wraiths","monsters":[{"name":"Wraith","count":2,"hp":67,"ac":13,"attack":"life drain +6, 4d8"}],"tactics":"They defend the inbox from anyone searching it.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["A letter of credit (400 gp)","An urgent summons addressed to the party"],"dmNotes":""},{"id":"tropelandia.room.lichs-filing-office.05-the-records-hall","number":5,"code":"LCH-05","name":"The Records Hall","floor":0,"pos":[0,2],"light":"cold blue","size":"120 x 80 ft","exits":[{"dir":"n","to":"tropelandia.room.lichs-filing-office.02-the-waiting-hall","kind":"archway","state":"open","note":""},{"dir":"s","to":"tropelandia.room.lichs-filing-office.08-the-lichs-corner-office","kind":"door","state":"locked","note":"Locked by the Lich's seal"},{"dir":"e","to":"tropelandia.room.lichs-filing-office.06-phylactery-storage","kind":"archway","state":"open","note":""},{"dir":"w","to":"tropelandia.room.lichs-filing-office.07-appeals","kind":"archway","state":"open","note":""}],"readAloud":"A vast gallery of towering filing cabinets reaching beyond sight. Each drawer is labelled with a name, a date and a number. Cold blue light drifts through the aisles. A small golem on wheels glides past with a stack of files.","features":["Towering filing cabinets","A golem courier","Drawers labelled with names"],"encounters":[{"name":"Filing golem","monsters":[{"name":"Stone golem","count":1,"hp":178,"ac":17,"attack":"slam +10, 3d8+6"}],"tactics":"It defends the cabinets from vandals.","treasure":""}],"traps":[],"puzzles":[{"name":"The File","description":"The party's own file is somewhere in the cabinets, and it contains a clause that could free them.","solution":"Search by name and date (Investigation DC 14).","hints":["Files are alphabetical by cause of death.","The golem knows the system.","The file is in the 'Pending' drawer."],"reward":"A shortcut and leverage over the Lich."}],"secrets":[],"loot":[],"dmNotes":""},{"id":"tropelandia.room.lichs-filing-office.06-phylactery-storage","number":6,"code":"LCH-06","name":"Phylactery Storage","floor":0,"pos":[1,2],"light":"glowing","size":"60 x 40 ft","exits":[{"dir":"n","to":"tropelandia.room.lichs-filing-office.03-the-forms-desk","kind":"door","state":"open","note":""},{"dir":"w","to":"tropelandia.room.lichs-filing-office.05-the-records-hall","kind":"archway","state":"open","note":""}],"readAloud":"A cold vault of glass shelves, each holding a small jar or amulet that glows with a faint inner light. Row upon row of phylacteries, each labelled with a name. A single, particularly ornate one sits in a pedestal case at the end, marked: PROPERTY OF L. VEXMORT. DO NOT TOUCH.","features":["Shelves of phylacteries","A pedestal case","A cold draught"],"encounters":[],"traps":[{"name":"Phylactery ward","trigger":"Touching the pedestal","effect":"DC 17 Con save or 8d6 necrotic","detect_dc":18,"disarm_dc":17}],"puzzles":[],"secrets":[],"loot":["The Lich's phylactery (breaking it ends Vexmort for good)","Dozens of other souls' phylacteries (free them for story rewards)"],"dmNotes":"The key objective. The Lich will fight to defend it."},{"id":"tropelandia.room.lichs-filing-office.07-appeals","number":7,"code":"LCH-07","name":"Appeals","floor":0,"pos":[-1,2],"light":"solemn","size":"50 x 40 ft","exits":[{"dir":"n","to":"tropelandia.room.lichs-filing-office.04-the-inbox","kind":"door","state":"open","note":""},{"dir":"e","to":"tropelandia.room.lichs-filing-office.05-the-records-hall","kind":"archway","state":"open","note":""}],"readAloud":"A courtroom-like chamber where a row of ghostly judges sits behind a long bench. A gavel bangs. A petitioner at the stand pleads, 'But I was alive when I filed.' 'Denied,' say the judges. 'Next!'","features":["Ghostly judges","A witness stand","A scales of justice, slightly off"],"encounters":[{"name":"Appeals panel","monsters":[{"name":"Ghost judge","count":3,"hp":45,"ac":11,"attack":"withering touch +5, 4d6"}],"tactics":"They rule on the party's case; they can be persuaded by good arguments (Persuasion DC 16).","treasure":""}],"traps":[],"puzzles":[{"name":"The Appeal","description":"The party can appeal the Lich's rule. Winning grants a stay of execution.","solution":"Make a case (Persuasion DC 16) citing a procedural error found in the Records Hall.","hints":["Procedural errors are the key.","The judges love precedent.","The Lich hates being overruled."],"reward":"The judges grant a one-time reprieve from the Lich's wrath."}],"secrets":[],"loot":[],"dmNotes":""},{"id":"tropelandia.room.lichs-filing-office.08-the-lichs-corner-office","number":8,"code":"LCH-08","name":"The Lich's Corner Office","floor":0,"pos":[0,3],"light":"starlight","size":"60 x 50 ft","exits":[{"dir":"n","to":"tropelandia.room.lichs-filing-office.05-the-records-hall","kind":"door","state":"locked","note":"Locked by the Lich's seal"}],"readAloud":"A vast corner office with a wall of windows that look onto a sea of stars. An obsidian desk dominates the room, behind it a tall skeletal figure in an immaculate robe, quill in hand. He does not look up. 'I've been expecting you. You are twelve minutes late. I trust you have filed the appropriate forms.'","features":["An obsidian desk","A wall of windows onto stars","A stack of forms"],"encounters":[{"name":"Lord Vexmort","monsters":[{"name":"Lich (Lord Vexmort)","count":1,"hp":135,"ac":17,"attack":"paralysing touch +12, 3d6 cold; spells: power word kill, disintegrate, counterspell"}],"tactics":"He fights if the party attacks, or tries to take the phylactery. He first offers them a form and a deal: sign here, and live forever, in the Office.","treasure":""}],"traps":[],"puzzles":[{"name":"The Deal","description":"Lord Vexmort offers the party eternal jobs in the Office. The contract is a trap.","solution":"Read the fine print (Investigation DC 17), or destroy the phylactery first.","hints":["He keeps pushing a pen.","The contract names the signatory's soul.","His phylactery is in the vault."],"reward":"Free from the contract, and the Lich is weakened."}],"secrets":[],"loot":["The Lich's quill (writes any contract)","A cloak of undeath resistance","The deed to the Office of Eternal Records"],"dmNotes":"Lich played as a bureaucrat: the final boss is a paperwork fight. The phylactery makes it mechanical."}]},{"id":"tropelandia.dungeon.restricted-section","code":"ACD","name":"The Restricted Section","universe":"tropelandia","place":{"id":"tropelandia.region.scholars-spire","name":"Scholars' Spire","path":["Tropelandia","Material Plane","Gleamhaven","Mildew Sun","Tropos","Mainland","Scholars' Spire"]},"levelRange":[6,8],"tone":"scholarly puzzle","tags":["library","wizard-academy","puzzles","books","magic"],"summary":"The Restricted Section of the Thaumaturgic Academy at Scholars' Spire holds every book that was too dangerous to burn, too embarrassing to lose and too interesting to ignore. The books bite, the shelves rearrange and the Librarian has seen every excuse. A student's overdue book is the party's excuse to go inside.","hooks":["Retrieve an overdue book.","Find a spell the Dean forgot.","Investigate the student who vanished into the stacks."],"rumours":["The books are alive and a bit hungry.","The Librarian is older than the Academy.","Nobody's ever finished the Forbidden Index."],"wandering":{"die":"d6","entries":["1: A book flaps past, snapping","2: Shelves rearrange; the path home changes","3: A student ghost asks for a reference","4: Whispers from a banned poetry book","5: A scroll unrolls and tries to read you","6: A distant, furious SHHH"]},"tropes":["Wizard Academy","Lich","Dungeon with No Logical Layout"],"author":"seth","status":"sample","entry":"tropelandia.room.restricted-section.01-the-librarians-desk","rooms":[{"id":"tropelandia.room.restricted-section.01-the-librarians-desk","number":1,"code":"ACD-01","name":"The Librarian's Desk","floor":0,"pos":[0,0],"light":"lamplight","size":"30 x 20 ft","exits":[{"dir":"s","to":"tropelandia.room.restricted-section.02-silent-reading-room","kind":"door","state":"closed","note":"Iron doors; open on presentation of a library card"},{"dir":"out","to":"outside","kind":"door","state":"open","note":"The Academy corridor"}],"readAloud":"A vast oak desk stands before a pair of iron doors, behind it a very old woman with spectacles on a chain. She does not look up. 'Library card,' she says. 'Overdue fines. And the rules, which you have not read.' A small brass bell chimes by itself.","features":["A vast oak desk","A brass bell","A stack of fine notices"],"encounters":[{"name":"The Librarian","monsters":[{"name":"Archmage Librarian (mage)","count":1,"hp":40,"ac":12,"attack":"fire bolt +6, 2d10"}],"tactics":"She attacks only if the rules are broken in front of her; she also enforces silence with a spell.","treasure":""}],"traps":[],"puzzles":[{"name":"The Rules","description":"The Librarian demands that the party read the rules and sign a waiver. The waiver contains a hidden clause.","solution":"Read the waiver (Investigation DC 14) to find and strike the clause 'owes a year of service'.","hints":["The waiver has an asterisk.","Page 3 is blank, then isn't.","A signature is a binding contract."],"reward":"The iron doors open."}],"secrets":[],"loot":[],"dmNotes":""},{"id":"tropelandia.room.restricted-section.02-silent-reading-room","number":2,"code":"ACD-02","name":"Silent Reading Room","floor":0,"pos":[0,1],"light":"green lamplight","size":"60 x 40 ft","exits":[{"dir":"n","to":"tropelandia.room.restricted-section.01-the-librarians-desk","kind":"door","state":"closed","note":"Iron doors; open on presentation of a library card"},{"dir":"s","to":"tropelandia.room.restricted-section.05-the-stacks-labyrinth","kind":"archway","state":"open","note":""},{"dir":"e","to":"tropelandia.room.restricted-section.03-reference-shelves","kind":"door","state":"open","note":""},{"dir":"w","to":"tropelandia.room.restricted-section.04-banned-fiction","kind":"door","state":"open","note":""}],"readAloud":"A long, hushed hall of reading desks under green-shaded lamps. Students slump over books, motionless and pale. A sign: SILENCE. Even your footsteps seem to stir the pages, which rustle in warning.","features":["Rows of desks","Pale students (animated by books)","Green lamps"],"encounters":[{"name":"Bookbound students","monsters":[{"name":"Zombie student","count":4,"hp":22,"ac":8,"attack":"slam +3, 1d6+1"}],"tactics":"They rise if the party speaks above a whisper.","treasure":""}],"traps":[{"name":"The Silence spell","trigger":"Speaking loudly","effect":"A zone of magical silence: casters are blocked for 1 minute","detect_dc":14,"disarm_dc":0}],"puzzles":[],"secrets":[],"loot":[],"dmNotes":"Stealth makes the encounter trivial; noise makes it deadly."},{"id":"tropelandia.room.restricted-section.03-reference-shelves","number":3,"code":"ACD-03","name":"Reference Shelves","floor":0,"pos":[1,1],"light":"lamps","size":"40 x 30 ft","exits":[{"dir":"w","to":"tropelandia.room.restricted-section.02-silent-reading-room","kind":"door","state":"open","note":""}],"readAloud":"Floor-to-ceiling shelves of reference works, atlases and encyclopaedias. A ladder on tracks slides back and forth. A particularly thick volume on a lectern blinks open as you approach and says, in a deep voice, 'Query?'","features":["The Talking Encyclopedia","A sliding ladder","A map of the Restricted Section"],"encounters":[],"traps":[],"puzzles":[{"name":"The Encyclopedia","description":"The Encyclopedia answers one question per party member, but each question costs a secret.","solution":"Ask smart questions and answer honestly (Insight/Persuasion DC 13).","hints":["It values secrets.","It can lie.","It hates repeating itself."],"reward":"A key clue to the final vault."}],"secrets":[],"loot":["A map of the Section (reveals the layout of the Stacks)"],"dmNotes":""},{"id":"tropelandia.room.restricted-section.04-banned-fiction","number":4,"code":"ACD-04","name":"Banned Fiction","floor":0,"pos":[-1,1],"light":"rose-coloured","size":"30 x 30 ft","exits":[{"dir":"e","to":"tropelandia.room.restricted-section.02-silent-reading-room","kind":"door","state":"open","note":""}],"readAloud":"Shelves of lurid paperbacks and scandalous romances line the walls, their covers shifting and sighing. A reading chair bears a heart-shaped indent. A tiny tag on one shelf: 'READ AT YOUR OWN RISK. SERIOUSLY.'","features":["Sighing paperbacks","A reading chair","A shelf of dubious classics"],"encounters":[{"name":"Lovestruck tomes","monsters":[{"name":"Flying books","count":6,"hp":5,"ac":14,"attack":"paper cut +4, 1d4+1"}],"tactics":"They try to charm: DC 13 Wis save or the target is charmed for 1 minute.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["A romance novel that grants advantage on Persuasion for a day"],"dmNotes":""},{"id":"tropelandia.room.restricted-section.05-the-stacks-labyrinth","number":5,"code":"ACD-05","name":"The Stacks Labyrinth","floor":0,"pos":[0,2],"light":"floating lanterns","size":"100 x 100 ft","exits":[{"dir":"n","to":"tropelandia.room.restricted-section.02-silent-reading-room","kind":"archway","state":"open","note":""},{"dir":"s","to":"tropelandia.room.restricted-section.09-the-forbidden-index","kind":"passage","state":"open","note":""},{"dir":"u","to":"tropelandia.room.restricted-section.06-the-catwalk","kind":"ladder","state":"open","note":""}],"readAloud":"A labyrinth of towering shelves stretches in every direction, lit by floating lanterns. The aisles shift when not observed, and the signs overhead say 'A-F', 'G-M', 'Nope' and 'You Are Here'. Somewhere a student is crying.","features":["Shifting shelves","Floating lanterns","Conflicting signs"],"encounters":[{"name":"Lost student ghosts","monsters":[{"name":"Specter","count":2,"hp":22,"ac":12,"attack":"life drain +4, 3d6"}],"tactics":"They are lost and want to be shown the exit; they attack if frightened.","treasure":""}],"traps":[],"puzzles":[{"name":"The Shifting Aisles","description":"The aisles move when unobserved. The party must navigate by the Dewey code on the shelf ends.","solution":"Follow the code 'Magic, Misc., Misc., Misc.' (Survival DC 14) or use the Section map.","hints":["The signs lie.","Shelf ends have codes.","The map in Reference helps."],"reward":"The path to the Forbidden Index."}],"secrets":[],"loot":[],"dmNotes":""},{"id":"tropelandia.room.restricted-section.06-the-catwalk","number":6,"code":"ACD-06","name":"The Catwalk","floor":1,"pos":[0,2],"light":"starlit","size":"80 x 10 ft","exits":[{"dir":"e","to":"tropelandia.room.restricted-section.07-rare-manuscripts","kind":"door","state":"open","note":""},{"dir":"w","to":"tropelandia.room.restricted-section.08-the-deans-private-reserve","kind":"door","state":"open","note":""},{"dir":"d","to":"tropelandia.room.restricted-section.05-the-stacks-labyrinth","kind":"ladder","state":"open","note":""}],"readAloud":"A web of iron catwalks high above the stacks. Wind whistles through the shelves; below, the lanterns look like stars. Along the catwalk, doors lead to the Dean's private reserve and the Rare Manuscripts.","features":["Iron catwalks","A view down the Stacks","Brass signposts"],"encounters":[{"name":"Gargoyle librarians","monsters":[{"name":"Gargoyle","count":2,"hp":52,"ac":15,"attack":"claws +4, 2d6+2"}],"tactics":"They perch above the catwalk and drop on anyone shouting.","treasure":""}],"traps":[{"name":"Rotten walkway","trigger":"Running on the catwalk","effect":"DC 13 Dex save or fall 30 ft","detect_dc":14,"disarm_dc":0}],"puzzles":[],"secrets":[],"loot":[],"dmNotes":""},{"id":"tropelandia.room.restricted-section.07-rare-manuscripts","number":7,"code":"ACD-07","name":"Rare Manuscripts","floor":1,"pos":[1,2],"light":"dim, filtered","size":"40 x 30 ft","exits":[{"dir":"w","to":"tropelandia.room.restricted-section.06-the-catwalk","kind":"door","state":"open","note":""}],"readAloud":"A hushed chamber of glass cases, each holding a book bound in something that was once alive. Dust motes hang in the stillness. A single illuminated manuscript lies open on a lectern, its illustrations moving slowly.","features":["Glass cases","An illuminated manuscript","A lectern"],"encounters":[],"traps":[{"name":"Glass case ward","trigger":"Opening a case without a key","effect":"DC 14 Dex save or 4d6 force","detect_dc":15,"disarm_dc":14}],"puzzles":[],"secrets":[],"loot":["A spellbook with 3 random wizard spells (up to level 3)","A bookmark of Feather Fall"],"dmNotes":""},{"id":"tropelandia.room.restricted-section.08-the-deans-private-reserve","number":8,"code":"ACD-08","name":"The Dean's Private Reserve","floor":1,"pos":[-1,2],"light":"warm","size":"30 x 25 ft","exits":[{"dir":"e","to":"tropelandia.room.restricted-section.06-the-catwalk","kind":"door","state":"open","note":""}],"readAloud":"A cosy study with leather armchairs, a crystal decanter and a wall of the Dean's favourite secrets. A man in a moth-eaten robe snores in an armchair, a book across his chest: 'How to Avoid Doing Anything.'","features":["The Dean (asleep)","A decanter","A wall of secrets"],"encounters":[{"name":"The Dean","monsters":[{"name":"Archmage-in-retirement (mage)","count":1,"hp":40,"ac":12,"attack":"firebolt +6, 2d10"}],"tactics":"He wakes if the decanter is touched. He's grumpy but fair.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["A potion of invisibility (the Dean's emergency exit)","A leather-bound journal of the Academy's secrets"],"dmNotes":""},{"id":"tropelandia.room.restricted-section.09-the-forbidden-index","number":9,"code":"ACD-09","name":"The Forbidden Index","floor":0,"pos":[0,3],"light":"faint glow","size":"40 ft diameter","exits":[{"dir":"n","to":"tropelandia.room.restricted-section.05-the-stacks-labyrinth","kind":"passage","state":"open","note":""}],"readAloud":"At the heart of the Stacks lies a circular chamber with a single pedestal. Upon it rests a large book chained shut, its cover shifting between a dozen languages. A voice comes from the book: 'Hello. Would you like to read me?'","features":["A chained book","A single pedestal","An inscription: 'ASK, AND BE ANSWERED'"],"encounters":[{"name":"The Forbidden Index","monsters":[{"name":"Living book (aberration)","count":1,"hp":90,"ac":15,"attack":"psychic lash +7, 3d8"}],"tactics":"It wants a reader; it attacks if refused. It can be bargained with: one answer for one favour.","treasure":""}],"traps":[],"puzzles":[{"name":"The Reading","description":"The book will answer one question, truthfully, in exchange for a secret of the reader's.","solution":"Offer a true secret (Persuasion DC 15) and ask a precise question.","hints":["It likes true secrets.","It hates evasion.","Be specific."],"reward":"An answer that changes the campaign."}],"secrets":[],"loot":["Knowledge (the DM's choice of plot reveal)"],"dmNotes":""}]},{"id":"tropelandia.dungeon.sunken-chapel","code":"CHP","name":"The Sunken Chapel of Mild Dread","universe":"tropelandia","place":{"id":"tropelandia.region.gently-haunted-marsh","name":"Gently Haunted Marsh","path":["Tropelandia","Material Plane","Gleamhaven","Mildew Sun","Tropos","Mainland","Gently Haunted Marsh"]},"levelRange":[2,4],"tone":"gothic parody","tags":["undead","water","marsh","crypt","bells"],"summary":"A small chapel that sank into the Gently Haunted Marsh centuries ago and refuses to finish the job. Its bell still rings at midnight, its dead are polite but persistent, and its altar is wanted by three different cults, none of whom has remembered to bring a boat.","hooks":["Recover the chapel's bell for the village of Barrowdale.","Escort a priest who wants to bless the dead.","Find the relic three cults are fighting over."],"rumours":["The bell rings by itself at midnight; one note is flat and the dead are very sensitive about it.","The priest vanished here and sends angry letters from the crypt.","A reliquary glows under the water; touching it makes you sneeze."],"wandering":{"die":"d6","entries":["1: The bell rings; all undead in the chapel wake up","2: 1d4 skeletons shuffle past, nodding politely","3: A cold spot; a ghostly voice asks directions","4: A swarm of marsh bats (hp 5, AC 12)","5: Water rises 1 ft; disadvantage on Dex","6: A distant hymn, slightly off-key"]},"tropes":["Dungeon with No Logical Layout","Ancient Evil Released by Dumb Adventurers","Cult Summoning a Demon"],"author":"seth","status":"sample","entry":"tropelandia.room.sunken-chapel.01-reed-landing","rooms":[{"id":"tropelandia.room.sunken-chapel.01-reed-landing","number":1,"code":"CHP-01","name":"Reed Landing","floor":0,"pos":[0,0],"light":"mist and moonlight","size":"20 x 10 ft","exits":[{"dir":"s","to":"tropelandia.room.sunken-chapel.02-the-nave","kind":"door","state":"stuck","note":"DC 12 Str to force"}],"readAloud":"A broken wooden jetty pokes out of the reeds, leading to a half-sunken chapel door. Mist coils over black water; frogs fall silent as you approach. The door, swollen with damp, bears a hand-painted sign: PLEASE WIPE YOUR FEET (AND YOUR MEMORIES).","features":["A rotten jetty","Frog silence","A mooring post with a ghostly rope"],"encounters":[{"name":"Reed-lurkers","monsters":[{"name":"Giant frog","count":3,"hp":18,"ac":11,"attack":"bite +3, 1d6+1, swallow"}],"tactics":"They ambush from the water as the party approaches the door.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["A pouch of lost coins in the reeds (25 gp)"],"dmNotes":""},{"id":"tropelandia.room.sunken-chapel.02-the-nave","number":2,"code":"CHP-02","name":"The Nave","floor":0,"pos":[0,1],"light":"moonlight","size":"40 x 20 ft, 2 ft of water","exits":[{"dir":"n","to":"tropelandia.room.sunken-chapel.01-reed-landing","kind":"door","state":"stuck","note":"DC 12 Str to force"},{"dir":"s","to":"tropelandia.room.sunken-chapel.05-the-altar","kind":"archway","state":"open","note":""},{"dir":"e","to":"tropelandia.room.sunken-chapel.04-the-vestry","kind":"door","state":"open","note":""},{"dir":"w","to":"tropelandia.room.sunken-chapel.03-bell-tower-base","kind":"door","state":"open","note":""}],"readAloud":"The long hall of a chapel half under water. Pews float like islands, their cushions long dissolved. Moonlight falls through a broken window onto an altar draped in algae. Skeletal worshippers kneel in the pews, heads bowed, perfectly still.","features":["Floating pews","Kneeling skeletons (inert unless disturbed)","A cracked stained-glass window"],"encounters":[{"name":"Congregation","monsters":[{"name":"Skeleton","count":6,"hp":13,"ac":13,"attack":"shortsword +4, 1d6+2"}],"tactics":"They rise if the party touches the altar or disturbs the pews; they will sing, loudly, off-key, which gives disadvantage on Wisdom (Perception).","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":[],"dmNotes":"Passive hazard: moving quietly keeps the congregation asleep (DC 12 Stealth)."},{"id":"tropelandia.room.sunken-chapel.03-bell-tower-base","number":3,"code":"CHP-03","name":"Bell Tower Base","floor":0,"pos":[-1,1],"light":"dim","size":"15 x 15 ft","exits":[{"dir":"e","to":"tropelandia.room.sunken-chapel.02-the-nave","kind":"door","state":"open","note":""},{"dir":"u","to":"tropelandia.room.sunken-chapel.09-the-belfry","kind":"ladder","state":"open","note":"An iron ladder, rusted but sound"}],"readAloud":"A tight stone chamber at the foot of the bell tower. A rope as thick as your wrist hangs from above, wet and dark. Somewhere high up, a bell sways with a sound like a sad cow.","features":["The bell rope","A hole in the floor to the water below","Scratches on the wall: 'DON'T RING IT'"],"encounters":[],"traps":[{"name":"The bell rope","trigger":"Pulling the bell rope","effect":"The bell sounds: all undead in the chapel awaken and approach; DC 13 Con save or deafened for 1 minute","detect_dc":12,"disarm_dc":0}],"puzzles":[],"secrets":[],"loot":[],"dmNotes":""},{"id":"tropelandia.room.sunken-chapel.04-the-vestry","number":4,"code":"CHP-04","name":"The Vestry","floor":0,"pos":[1,1],"light":"dim","size":"15 x 15 ft","exits":[{"dir":"w","to":"tropelandia.room.sunken-chapel.02-the-nave","kind":"door","state":"open","note":""}],"readAloud":"A small side room with a locked cabinet, a moth-eaten vestment on a hook and a table laid for a meal nobody finished. A priest in a mouldering cassock sits at the table with a fork in his hand, staring at an empty plate with infinite patience.","features":["A locked cabinet (DC 14)","A table set for dinner","The Priest (a ghost)"],"encounters":[{"name":"The Priest","monsters":[{"name":"Ghost of Father Mildred","count":1,"hp":45,"ac":11,"attack":"withering touch +5, 4d6 (only if provoked)"}],"tactics":"He wants someone to finish his sermon. If the party listens, he gives them his blessing and the cabinet key.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["A silver holy symbol worth 25 gp","The vestry key","A prayer scroll (bless x1)"],"dmNotes":"A good place for a roleplay break; the priest can offer clues about the altar."},{"id":"tropelandia.room.sunken-chapel.05-the-altar","number":5,"code":"CHP-05","name":"The Altar","floor":0,"pos":[0,2],"light":"pale candles","size":"25 x 20 ft","exits":[{"dir":"n","to":"tropelandia.room.sunken-chapel.02-the-nave","kind":"archway","state":"open","note":""},{"dir":"d","to":"tropelandia.room.sunken-chapel.06-the-crypt","kind":"stairs","state":"open","note":"A spiral stair behind the altar"}],"readAloud":"The altar stands on a raised platform, draped in a green-black cloth. Candles burn with a pale flame that does not flicker. On the altar rests a bronze reliquary the size of a loaf of bread, covered in tiny sigils. A staircase behind the altar leads down into the crypt.","features":["The reliquary","Pale candles","A shaft of moonlight directly on the altar"],"encounters":[],"traps":[{"name":"Reliquary ward","trigger":"Lifting the reliquary without the blessing","effect":"A pulse of necrotic energy: DC 13 Wis save or 3d6 necrotic and frightened for 1 minute","detect_dc":14,"disarm_dc":14}],"puzzles":[{"name":"The Blessing","description":"The reliquary can be taken safely if the party performs a short blessing. The right words are written on the priest's vestments.","solution":"Recite the blessing from the vestry (Religion DC 12 or ask the priest).","hints":["The vestment has stitching.","The priest's sermon is the key.","Bless works as a shortcut."],"reward":"Take the reliquary safely."}],"secrets":[],"loot":["The Reliquary of Mild Dread (worth 200 gp; sneezes when touched)"],"dmNotes":""},{"id":"tropelandia.room.sunken-chapel.06-the-crypt","number":6,"code":"CHP-06","name":"The Crypt","floor":-1,"pos":[0,2],"light":"dark","size":"35 x 25 ft, 1 ft of water","exits":[{"dir":"e","to":"tropelandia.room.sunken-chapel.07-the-drowned-ossuary","kind":"archway","state":"open","note":""},{"dir":"w","to":"tropelandia.room.sunken-chapel.08-the-weeping-reliquary","kind":"archway","state":"open","note":""},{"dir":"u","to":"tropelandia.room.sunken-chapel.05-the-altar","kind":"stairs","state":"open","note":""}],"readAloud":"A vaulted crypt lined with stone niches, each holding a skeleton in rotted finery. The water is knee-deep and ice-cold; the air tastes of tombs. A rusted chain of keys hangs from a skeleton's belt near the north wall.","features":["Stone niches","A skeleton with keys","Cold, still water"],"encounters":[{"name":"Crypt guardians","monsters":[{"name":"Zombie","count":3,"hp":22,"ac":8,"attack":"slam +3, 1d6+1"},{"name":"Ghoul","count":1,"hp":22,"ac":12,"attack":"claws +4, 2d4+2 (paralysis)"}],"tactics":"The ghoul lurks until the party is distracted by the zombies, then strikes.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["A ring of keys (opens the vestry cabinet and the reliquary vault)"],"dmNotes":""},{"id":"tropelandia.room.sunken-chapel.07-the-drowned-ossuary","number":7,"code":"CHP-07","name":"The Drowned Ossuary","floor":-1,"pos":[1,2],"light":"dark","size":"30 ft diameter, 2 ft of water","exits":[{"dir":"w","to":"tropelandia.room.sunken-chapel.06-the-crypt","kind":"archway","state":"open","note":""}],"readAloud":"A circular chamber stacked to the ceiling with bones in neat, almost artistic arrangements. Water laps at the floor. In the centre stands a pillar made entirely of skulls, whose empty sockets seem to turn to follow you.","features":["Bone patterns","The skull pillar","A shallow pool at the centre"],"encounters":[{"name":"Bone swarm","monsters":[{"name":"Swarm of bones (skeletons)","count":1,"hp":30,"ac":11,"attack":"rattle +4, 2d6"}],"tactics":"Triggers if the pillar is smashed rather than solved.","treasure":""}],"traps":[],"puzzles":[{"name":"The Skull Pillar","description":"Eight skulls on the pillar can be rotated. One of them is slightly different.","solution":"Rotate the skulls to face the door in order of the saints' calendar (Religion DC 13) to open a hidden niche.","hints":["The skulls have tiny carved numbers.","The saints' calendar is in the priest's vestry.","Rotating the odd one out reveals a catch."],"reward":"A hidden niche holding the Bone Key and 100 gp."}],"secrets":[],"loot":["The Bone Key (opens the reliquary vault)","100 gp in ancient coins"],"dmNotes":""},{"id":"tropelandia.room.sunken-chapel.08-the-weeping-reliquary","number":8,"code":"CHP-08","name":"The Weeping Reliquary","floor":-1,"pos":[-1,2],"light":"dark","size":"20 x 20 ft","exits":[{"dir":"e","to":"tropelandia.room.sunken-chapel.06-the-crypt","kind":"archway","state":"open","note":""}],"readAloud":"A small chamber sealed by an iron gate. Inside, a stone sarcophagus weeps a continuous stream of cold water. Above it hangs a faded fresco of a saint holding a bell, gazing sadly at a very large puddle.","features":["The weeping sarcophagus","A fresco of the saint","An iron gate (DC 15 or the Bone Key)"],"encounters":[{"name":"The Weeping Saint","monsters":[{"name":"Specter","count":1,"hp":22,"ac":12,"attack":"life drain +4, 3d6"}],"tactics":"The specter attacks anyone who disturbs the sarcophagus.","treasure":""}],"traps":[],"puzzles":[],"secrets":[{"description":"A hidden compartment in the fresco holds the Chapel's true relic: a small silver bell","dc":15}],"loot":["The Saint's Silver Bell (works as a ring of protection when rung, once per day)"],"dmNotes":""},{"id":"tropelandia.room.sunken-chapel.09-the-belfry","number":9,"code":"CHP-09","name":"The Belfry","floor":1,"pos":[-1,1],"light":"windy, moonlit","size":"20 ft diameter","exits":[{"dir":"d","to":"tropelandia.room.sunken-chapel.03-bell-tower-base","kind":"ladder","state":"open","note":""}],"readAloud":"At the top of the tower the bell hangs, huge and green with age, its clapper tied with a mouldering ribbon. Wind shrieks through the open arches. A pair of gargoyles perch on the rim, perfectly still, and one of them blinks.","features":["The huge bell","Two gargoyles","A view over the entire marsh"],"encounters":[{"name":"Gargoyle sentries","monsters":[{"name":"Gargoyle","count":2,"hp":52,"ac":15,"attack":"claws +4, 2d6+2"}],"tactics":"They attack if the bell is tampered with; they'll let the party ring it if asked politely.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["The Bell itself (worth 500 gp to a church, and more to a cult)"],"dmNotes":"The bell is the quest item; ringing it correctly (three notes) puts the chapel's dead to rest."}]},{"id":"tropelandia.dungeon.mimic-inn","code":"INN","name":"Ye Olde Mimic Inn","universe":"tropelandia","place":{"id":"tropelandia.region.whisperwood","name":"Whisperwood","path":["Tropelandia","Material Plane","Gleamhaven","Mildew Sun","Tropos","Mainland","Whisperwood"]},"levelRange":[4,6],"tone":"horror comedy","tags":["mimic","inn","roadside","trap","lodging"],"summary":"The Roadside Welcome is the nicest inn in Whisperwood: clean beds, hot food, cheap rooms, and a landlord who never seems to leave the kitchen. It is also a single enormous mimic, gently digesting guests. The inn is happy to have you; it hasn't eaten in a week.","hooks":["Spend the night at the inn.","Find the missing merchants.","Burn the inn down (not recommended)."],"rumours":["Nobody's ever checked out of Room 7.","The soup tastes of regret.","The inn is warmer than it should be."],"wandering":{"die":"d6","entries":["1: The floor warms alarmingly","2: A door opens by itself","3: A guest in a nightgown walks past, glassy-eyed","4: Tentacles retract into the wall","5: The innkeeper offers a free drink","6: A distant, satisfied sigh"]},"tropes":["Mimic","The Tavern Where It All Starts","Dungeon with No Logical Layout"],"author":"seth","status":"sample","entry":"tropelandia.room.mimic-inn.01-the-common-room","rooms":[{"id":"tropelandia.room.mimic-inn.01-the-common-room","number":1,"code":"INN-01","name":"The Common Room","floor":0,"pos":[0,0],"light":"firelit","size":"40 x 30 ft","exits":[{"dir":"e","to":"tropelandia.room.mimic-inn.02-the-kitchen","kind":"door","state":"open","note":""},{"dir":"u","to":"tropelandia.room.mimic-inn.03-upstairs-landing","kind":"stairs","state":"open","note":""},{"dir":"d","to":"tropelandia.room.mimic-inn.07-the-wine-cellar","kind":"hatch","state":"open","note":""},{"dir":"out","to":"outside","kind":"door","state":"open","note":"The road"}],"readAloud":"A warm, welcoming common room with a roaring fire, long tables and a bar of polished oak. A cheerful innkeeper wipes a glass. The beams are slightly too fleshy, and the fire gives off no smoke. There is a faint, patient, wet sound, like breathing.","features":["A roaring fire","A smiling innkeeper","Tables of stew"],"encounters":[{"name":"The Innkeeper","monsters":[{"name":"Innkeeper (mimic extension)","count":1,"hp":58,"ac":12,"attack":"pseudopod +5, 1d8+3 plus adhesion"}],"tactics":"He tries to keep guests comfortable; if the party tries to leave he blocks doors with the building itself.","treasure":""}],"traps":[{"name":"Sticky floor","trigger":"Standing still too long","effect":"The floor adheres: DC 13 Str to pull free","detect_dc":14,"disarm_dc":0}],"puzzles":[],"secrets":[],"loot":[],"dmNotes":"Hint: all exits seem to close behind the party. Wisdom (Perception) DC 15 notices there is no draught."},{"id":"tropelandia.room.mimic-inn.02-the-kitchen","number":2,"code":"INN-02","name":"The Kitchen","floor":0,"pos":[1,0],"light":"steam","size":"30 x 20 ft","exits":[{"dir":"w","to":"tropelandia.room.mimic-inn.01-the-common-room","kind":"door","state":"open","note":""}],"readAloud":"A steaming kitchen with hanging pots and a great cauldron. Something simmers within, smelling almost, but not quite, like stew. A chopping board holds half a cheese, still wriggling.","features":["A huge cauldron","A wriggling cheese","A row of identical knives"],"encounters":[{"name":"Cook's apprentice","monsters":[{"name":"Mimic spawn","count":2,"hp":20,"ac":12,"attack":"bite +4, 1d6+2"}],"tactics":"Hatchlings play at being plates and cutlery; they bite if the party tries to eat.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["A cauldron of stew (heals 1d8, but you're sleepy)"],"dmNotes":""},{"id":"tropelandia.room.mimic-inn.03-upstairs-landing","number":3,"code":"INN-03","name":"Upstairs Landing","floor":1,"pos":[0,0],"light":"dim","size":"40 x 10 ft","exits":[{"dir":"s","to":"tropelandia.room.mimic-inn.06-the-linen-closet","kind":"door","state":"open","note":""},{"dir":"e","to":"tropelandia.room.mimic-inn.04-the-honeymoon-suite","kind":"door","state":"open","note":""},{"dir":"w","to":"tropelandia.room.mimic-inn.05-room-seven","kind":"door","state":"open","note":""},{"dir":"d","to":"tropelandia.room.mimic-inn.01-the-common-room","kind":"stairs","state":"open","note":""}],"readAloud":"A long, dim landing lined with doors, each numbered in brass. The carpet squelches. A chandelier made of what might be teeth sways gently. At the end, Room 7 stands slightly open, a warm light spilling out.","features":["A carpet that squelches","A chandelier of teeth","Numbered doors"],"encounters":[],"traps":[{"name":"Hungry carpet","trigger":"Walking carelessly","effect":"The carpet grabs: DC 13 Str to pull free, 1d6 acid","detect_dc":13,"disarm_dc":0}],"puzzles":[],"secrets":[],"loot":[],"dmNotes":""},{"id":"tropelandia.room.mimic-inn.04-the-honeymoon-suite","number":4,"code":"INN-04","name":"The Honeymoon Suite","floor":1,"pos":[1,0],"light":"candlelit","size":"25 x 20 ft","exits":[{"dir":"w","to":"tropelandia.room.mimic-inn.03-upstairs-landing","kind":"door","state":"open","note":""}],"readAloud":"A luxurious suite with a four-poster bed and heart-shaped pillows. A pair of skeletons in a bridal gown and tuxedo lie in each other's arms under the sheets, covered in a thin film of mucus. The room smells of roses and digestion.","features":["A four-poster bed","Heart-shaped pillows","The newlyweds"],"encounters":[],"traps":[],"puzzles":[],"secrets":[{"description":"A ring on the skeleton's finger is the innkeeper's lure","dc":13}],"loot":["A diamond ring (150 gp)","A bottle of champagne (20 gp)"],"dmNotes":""},{"id":"tropelandia.room.mimic-inn.05-room-seven","number":5,"code":"INN-05","name":"Room Seven","floor":1,"pos":[-1,0],"light":"moonlit","size":"20 x 15 ft","exits":[{"dir":"e","to":"tropelandia.room.mimic-inn.03-upstairs-landing","kind":"door","state":"open","note":""}],"readAloud":"A comfortable room with a bed, a washstand and a window onto a night sky that doesn't match the actual sky. A pile of luggage sits in the corner, some of it moving. A guest book on the nightstand lists names, none of them crossed out.","features":["A bed that wants to be slept in","A false window","A guest book"],"encounters":[{"name":"Luggage","monsters":[{"name":"Mimic spawn","count":3,"hp":20,"ac":12,"attack":"bite +4, 1d6+2"}],"tactics":"Suitcases spring to life if the bed is touched.","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["The missing merchants' coin purses (300 gp)","A guest book with a final entry: 'help'"],"dmNotes":""},{"id":"tropelandia.room.mimic-inn.06-the-linen-closet","number":6,"code":"INN-06","name":"The Linen Closet","floor":1,"pos":[0,1],"light":"dark","size":"10 x 10 ft","exits":[{"dir":"n","to":"tropelandia.room.mimic-inn.03-upstairs-landing","kind":"door","state":"open","note":""}],"readAloud":"A narrow closet of folded sheets and towels, smelling of lavender. A ladder disappears into a hatch in the ceiling. A tag on the top shelf reads: DO NOT UNFOLD.","features":["Folded sheets","A ceiling hatch","A sealed linen bag"],"encounters":[],"traps":[{"name":"Folded sheet","trigger":"Unfolding the top sheet","effect":"The sheet is a mimic: 3d6 bludgeoning, DC 14 Str to escape","detect_dc":15,"disarm_dc":0}],"puzzles":[],"secrets":[],"loot":["A magic towel (grants advantage on one saving throw vs. fire)"],"dmNotes":""},{"id":"tropelandia.room.mimic-inn.07-the-wine-cellar","number":7,"code":"INN-07","name":"The Wine Cellar","floor":-1,"pos":[0,0],"light":"dim","size":"40 x 40 ft","exits":[{"dir":"e","to":"tropelandia.room.mimic-inn.08-the-stomach","kind":"archway","state":"open","note":"A fleshy tunnel"},{"dir":"u","to":"tropelandia.room.mimic-inn.01-the-common-room","kind":"hatch","state":"open","note":""}],"readAloud":"A vast cellar of racked bottles, each labelled with the name of a missing guest. Below the floor, something pulses slowly, like a heartbeat. The air is thick and warm.","features":["Racks of bottles","A pulsing floor","A guest register"],"encounters":[],"traps":[{"name":"Digestive fumes","trigger":"Staying more than 5 minutes","effect":"DC 13 Con save or poisoned","detect_dc":14,"disarm_dc":0}],"puzzles":[],"secrets":[],"loot":["The best wine in Whisperwood (150 gp)"],"dmNotes":""},{"id":"tropelandia.room.mimic-inn.08-the-stomach","number":8,"code":"INN-08","name":"The Stomach","floor":-1,"pos":[1,0],"light":"bioluminescent","size":"60 x 50 ft","exits":[{"dir":"w","to":"tropelandia.room.mimic-inn.07-the-wine-cellar","kind":"archway","state":"open","note":"A fleshy tunnel"}],"readAloud":"A vast, glistening chamber in the heart of the inn: walls of ribbed pink flesh, a pool of acid at its centre, and the half-digested remains of a hundred guests' possessions. At the far end, the Innkeeper's true form looms, an enormous mimic with a thousand tiny doors for mouths.","features":["Ribbed walls","A pool of acid","A mound of digested possessions"],"encounters":[{"name":"The Inn Itself","monsters":[{"name":"Giant mimic (the Inn)","count":1,"hp":180,"ac":12,"attack":"pseudopod +9, 2d10+5 plus adhesion; acid 3d8"}],"tactics":"It fights hard but fears fire; it tries to swallow the party. It can be bargained with: it wants a steady supply of food (like deliveries).","treasure":""}],"traps":[],"puzzles":[],"secrets":[],"loot":["A heap of guests' possessions (1,000 gp in goods)","The Innkeeper's Heart (a mimic core, alchemical value 500 gp)"],"dmNotes":"Option: a Persuasion check (DC 16) to broker a lasting arrangement with the inn: a regular meal delivery in exchange for safe lodging."}]}]};
